        "path.lesson.optimizers_momentum_adam": ("Оптимизаторы: импульс и Adam", "Optimizers: momentum and Adam"),
        "path.lesson.initialization_and_normalization": ("Инициализация и нормализация", "Initialization and normalization"),
        "path.lesson.tokenizer_bpe": ("Свой токенизатор", "Your own tokenizer"),
        "path.lesson.bigram_language_model": ("Счётчик пар и выборка", "The pair counter and sampling"),
        "path.lesson.sampling_and_generation": ("Как модель выбирает: top-k, top-p и поиск", "How a model chooses: top-k, top-p, and search"),
        "path.lesson.rl_bandits": ("Бандиты: исследовать или пользоваться", "Bandits: explore or exploit"),
        "path.lesson.rl_mdp_bellman": ("Ценность и уравнение Беллмана", "Value and the Bellman equation"),
        "path.lesson.rl_q_learning": ("Q-обучение: агент сам проходит лабиринт", "Q-learning: an agent learns a maze by itself"),
        "path.lesson.rl_policy_gradient": ("Градиент политики", "The policy gradient"),
        "path.lesson.finetuning_and_lora": ("Дообучение и LoRA", "Fine-tuning and LoRA"),
        "path.lesson.rlhf_from_preferences": ("RLHF: модель учится на твоих предпочтениях", "RLHF: a model learns from your preferences"),
        "path.lesson.reasoning_and_rlvr": ("Откуда берутся рассуждения", "Where reasoning comes from"),
        "path.lesson.constitutional_ai_and_dpo": ("Конституция и прямая оптимизация предпочтений", "A constitution and direct preference optimization"),
        "path.lesson.rag_from_scratch": ("RAG своими руками", "RAG by hand"),
        "path.lesson.agents_and_tools": ("Агент и инструменты своими руками", "An agent and tools by hand"),
        "path.lesson.evaluation_that_means_something": ("Оценка, которая что-то значит", "Evaluation that means something"),
        "path.lesson.scaling_laws_and_resources": ("Законы масштабирования и цена обучения", "Scaling laws and the price of training"),
        "path.lesson.data_for_language_models": ("Откуда берутся данные", "Where the data come from"),
        "path.lesson.interp_probes": ("Зонды: что знает модель внутри", "Probes: what a model knows inside"),
        "path.lesson.interp_superposition": ("Суперпозиция: больше признаков, чем измерений", "Superposition: more features than dimensions"),
        "path.lesson.interp_sparse_features": ("Разреженные признаки", "Sparse features"),
