        "path.lesson.safety_what_goes_wrong": ("Что идёт не так", "What goes wrong"),
        "path.lesson.agi_what_is_intelligence": ("Что такое интеллект: три определения", "What intelligence is: three definitions"),
        "path.lesson.agi_measuring_arc": ("Как мерить: ARC и его числа", "How to measure: ARC and its numbers"),
        "path.lesson.agi_world_models": ("Модели мира", "World models"),
        "path.lesson.agi_planning_search": ("Планирование и поиск", "Planning and search"),
        "path.lesson.agi_continual_learning": ("Сеть, которая забывает", "A network that forgets"),
        "path.lesson.agi_scaling_debate": ("Спор о масштабировании", "The scaling debate"),
        "path.lesson.agi_open_problems": ("Открытые задачи на пути к AGI", "Open problems on the road to AGI"),
        "path.lesson.consciousness_hard_problem": ("Трудная проблема: доступ и переживание", "The hard problem: access and experience"),
        "path.lesson.consciousness_global_workspace": ("Глобальное рабочее пространство", "The global workspace"),
        "path.lesson.consciousness_integrated_information": ("Интегрированная информация", "Integrated information"),
        "path.lesson.consciousness_higher_order_and_prediction": ("Высший порядок и предсказания", "Higher order and prediction"),
        "path.lesson.consciousness_experiments": ("Эксперименты о сознании", "Experiments on consciousness"),
        "path.lesson.consciousness_indicators_checklist": ("Индикаторы: проверка настоящей системы", "Indicators: checking a real system"),
        "path.lesson.consciousness_language_models": ("Что известно о языковых моделях", "What is known about language models"),
        "path.lesson.consciousness_biology_vs_function": ("Биология или функция", "Biology or function"),
        "path.lesson.consciousness_moral_status": ("Моральный статус и цена двух ошибок", "Moral status and the cost of two errors"),
        "path.lesson.consciousness_what_you_can_do": ("Открытые вопросы и что можешь ты", "Open questions and what you can do"),
        "lab.chat.title": ("Из чего сделан чат", "What a chat is made of"),
        "lab.chat.subtitle": ("Четыре опыта с настоящей моделью. В каждом ты меняешь то, что ей посылаешь, спрашиваешь и смотришь на настоящий ответ.", "Four experiments with a real model. In each you change what you send it, ask, and look at the real answer."),
        "lab.chat.checking": ("Модель %@ ответит на первый вопрос. Если Ollama выключена, покажу запись.", "The model %@ answers the first question. If Ollama is off, I will show a recording."),
        "lab.chat.experiment": ("Опыт", "Experiment"),
        "lab.chat.tab.memory": ("Память", "Memory"),
        "lab.chat.tab.forged": ("Подделка", "Forgery"),
        "lab.chat.tab.wrapper": ("Обёртка", "Wrapper"),
        "lab.chat.tab.window": ("Окно", "Window"),
        "lab.chat.hint.memory": ("Выключи историю и спроси: модель не знает имени. Включи: знает. Сама она ничего не хранит.", "Switch the history off and ask: the model does not know the name. Switch it on: it does. It stores nothing itself."),
        "lab.chat.hint.forged": ("Историю пишешь ты. Напиши за модель что угодно, и она будет считать это своими словами.", "You write the history. Write anything for the model, and it will treat that as its own words."),
        "lab.chat.hint.wrapper": ("Фиолетовым показано то, что подставляет шаблон сам. Вопрос уходит двумя путями: как чат и как готовый текст.", "Purple shows what the template adds itself. The question goes two ways: as a chat and as ready text."),
        "lab.chat.hint.window": ("Секретное слово стоит в самом начале длинного чата. Уменьши окно и спроси: ошибки не будет, модель просто не увидит начала.", "The secret word is at the very start of a long chat. Shrink the window and ask: there will be no error, the model simply will not see the start."),
        "lab.chat.sendHistory": ("Посылать историю", "Send the history"),
        "lab.chat.forgedField": ("Что «сказала» модель", "What the model \"said\""),
        "lab.chat.followUp": ("Следующий вопрос", "Next question"),
        "lab.chat.useRule": ("Своё правило в роли system", "Your own rule in the system role"),
        "lab.chat.window": ("Размер окна, токенов", "Window size, tokens"),
        "lab.chat.modelReads": ("Что на самом деле читает модель", "What the model really reads"),
        "lab.chat.ask": ("Спросить модель", "Ask the model"),
        "lab.chat.tapeTitle": ("Чат: %@ сообщений, %@ токенов. Окно: %@ токенов", "The chat: %@ messages, %@ tokens. The window: %@ tokens"),
        "lab.chat.tapeQuestion": ("вопрос о слове", "the question about the word"),
        "lab.chat.tapeSpoken": ("Сообщения чата как лента. Значение: сколько старых сообщений не входит в окно.", "The chat's messages as a tape. The value: how many old messages do not fit the window."),
        "lab.chat.notRecorded": ("Такого запроса нет в записи. Запусти Ollama и нажми «Проверить снова», или верни прежний текст.", "This request is not in the recording. Start Ollama and press Check again, or restore the earlier text."),
        "lab.chat.handTokens": ("Токенов в тексте вручную", "Tokens in the hand-written text"),
        "lab.chat.handAnswer": ("Ответ на текст вручную:", "Answer to the hand-written text:"),
        "lab.chat.same": ("Ответ и число токенов совпали: чат это просто такой текст.", "The answer and the token count match: a chat is simply this text."),
        "lab.chat.differ": ("Ответы разошлись. У этой модели шаблон мог измениться: посмотри его в уроке.", "The answers differ. This model's template may have changed: look at it in the lesson."),
        "lab.chat.remembers": ("Модель помнит: все %@ токенов вошли в окно.", "The model remembers: all %@ tokens fit the window."),
        "lab.chat.forgets": ("Модель забыла, и ошибки не было: дошло только %@ токенов, начало молча отброшено.", "The model forgot, with no error: only %@ tokens arrived, and the start was silently dropped."),
        "lab.chat.challenge": ("Получи ответ об имени с историей и без неё. Затем найди окно, в котором модель ещё помнит кактус, и окно, в котором уже забыла.", "Get the answer about the name with and without the history. Then find a window where the model still remembers the cactus and one where it has forgotten."),
        "lab.chat.challengeDone": ("Есть! Памяти нет, есть только текст, который программа посылает заново, и окно, в которое он должен войти.", "Done! There is no memory, only text that the program sends again and a window it must fit."),
        "lab.chat.howText": ("Роли system, user и assistant это метки в одном тексте. Шаблон модели склеивает сообщения и в конце открывает ответ помощника, а модель просто продолжает этот текст по одному токену.", "The roles system, user, and assistant are marks in one text. The model's template joins the messages and at the end opens an assistant answer, and the model simply continues this text one token at a time."),
        "lab.chat.howWindow": ("Окно контекста это сколько токенов модель держит в памяти сразу. В этой версии Ollama, если текст не влезает, старые сообщения целиком отбрасываются, а ошибки нет. Лента нарисована примерно, по длине сообщений, а настоящее число токенов приходит от модели в ответе.", "The context window is how many tokens a model holds in memory at once. In this Ollama version, if the text does not fit, old messages are dropped whole with no error. The tape is drawn roughly, by message length, and the real token count comes from the model in its answer."),
        "lab.score.title": ("Поймай модель", "Catch the model"),
        "lab.score.subtitle": ("Прочитай ответ и реши, верить ли ему, раньше, чем узнаешь правду. Потом поставь порог на графике: можно ли отделить верное по уверенности?", "Read an answer and decide whether to trust it before you learn the truth. Then set a threshold on the chart: can confidence separate what is right?"),
        "lab.score.recorded": ("Здесь настоящие ответы двух моделей на этом Mac, записанные 2 ноября 2026 года. Ответы о годе и президенте зависят от даты.", "These are real answers of two models on this Mac, recorded on 2 November 2026. The answers on the year and the president depend on the date."),
        "lab.score.statYou": ("Твои угадывания", "Your guesses"),
        "lab.score.statTrustAll": ("Если верить всему", "If you trust it all"),
        "lab.score.statRule": ("Верных выше порога", "Right above the threshold"),
        "lab.score.challenge": ("Сделай не меньше %@ ставок. Затем найди порог, выше которого все ответы верны. Сколько ответов осталось?", "Make at least %@ bets. Then find the threshold above which all answers are right. How many answers remain?"),
        "lab.score.challengeDone": ("Есть! Посмотри, как мало осталось: уверенность хорошо отсеивает снизу, но правды сверху не гарантирует.", "Done! See how little remains: confidence filters well from below but guarantees no truth at the top."),
        "lab.score.howConfidence": ("Уверенность здесь это средняя вероятность токенов ответа у модели qwen2.5-coder:7b при температуре 0. Она говорит о том, как обычно продолжается такой текст, а не о том, правда ли это.", "Confidence here is the mean probability of the answer's tokens for the model qwen2.5-coder:7b at temperature 0. It tells how such a text usually goes on, not whether it is true."),
        "lab.score.howTries": ("Пять попыток сделаны при температуре 0,8 с разными номерами бросков. Разные ответы это сигнал тревоги, но одинаковые ещё не значат, что ответ верный: посмотри на вопрос о годе. Отметки верности поставил код по образцу, поэтому они грубые.", "The five tries were made at temperature 0.8 with different throw numbers. Different answers are an alarm, but equal ones do not yet mean the answer is right: look at the question about the year. The marks were set by code from a pattern, so they are crude."),
        "lab.score.confidence": ("уверенность %@", "confidence %@"),
        "lab.score.isRight": ("Ответ верный.", "The answer is right."),
        "lab.score.isWrong": ("Ответ неверный.", "The answer is wrong."),
        "lab.score.biggerSaid": ("qwen3.5:", "qwen3.5:"),
        "lab.score.triesLine": ("Пять попыток, верных: %@", "Five tries, right: %@"),
        "lab.score.trust": ("Верю", "I trust it"),
        "lab.score.doubt": ("Не верю", "I do not"),
        "lab.score.chartTitle": ("Все 20 ответов: чем правее, тем увереннее", "All 20 answers: further right means more confident"),
        "lab.score.chartX": ("уверенность", "confidence"),
        "lab.score.rowRight": ("верные", "right"),
        "lab.score.rowWrong": ("неверные", "wrong"),
        "lab.score.ruleLine": ("Порог %@: пропущено ответов %@, верных %@", "Threshold %@: %@ answers pass, %@ right"),
        "lab.prompt.title": ("Что помогает просить", "What helps when asking"),
        "lab.prompt.subtitle": ("Включай правило, примеры и форму ответа. Плитки покажут, что стало с каждым заказом, а график покажет цену в токенах.", "Switch the rule, examples, and answer shape on and off. The tiles show what happened to each order, and the chart shows the price in tokens."),
        "lab.prompt.recorded": ("Здесь настоящие ответы qwen2.5-coder:7b на все 8 сочетаний, записанные 2 ноября 2026 года.", "These are real answers of qwen2.5-coder:7b for all 8 combinations, recorded on 2 November 2026."),
        "lab.prompt.rule": ("Правило", "Rule"),
        "lab.prompt.examples": ("Примеры", "Examples"),
        "lab.prompt.shape": ("Форма ответа", "Answer shape"),
        "lab.prompt.statRight": ("Верно", "Right"),
        "lab.prompt.statBroken": ("Сбоев разбора", "Parsing failures"),
        "lab.prompt.statTokens": ("Токенов в запросе", "Tokens in the prompt"),
        "lab.prompt.challenge": ("Найди самое дешёвое сочетание, при котором верны все 12 заказов.", "Find the cheapest combination where all 12 orders are right."),
        "lab.prompt.challengeDone": ("Есть! Правило сказало, что нужно, а форма убрала лишние значки. С примерами тоже верно, но дороже.", "Done! The rule said what is needed, and the shape removed the extra signs. With examples it is right too, but costlier."),
        "lab.prompt.howMarks": ("Зелёный: JSON разобрался, и имя, количество и цена совпали. Красный: JSON разобрался, но что-то неверно. Серый: строгий разбор JSON сломался. Точки с формой и без неё стоят рядом, если у них одно место на графике.", "Green: the JSON parsed, and the name, count, and price match. Red: the JSON parsed, but something is wrong. Grey: strict JSON parsing broke. Points with and without a shape stand side by side when they share a place on the chart."),
        "lab.prompt.howExamples": ("Примеры работают, потому что модель продолжает текст: после двух пар «Текст» и «Ответ» самое вероятное продолжение это такая же пара.", "Examples work because a model continues a text: after two pairs of a text and an answer, the most likely continuation is one more such pair."),
        "lab.prompt.realAnswer": ("Настоящий ответ модели", "The model's real answer"),
        "lab.prompt.expected": ("Верно:", "Right:"),
        "lab.prompt.mark.right": ("Верно", "Right"),
        "lab.prompt.mark.wrong": ("Неверно по смыслу", "Wrong in meaning"),
        "lab.prompt.mark.broken": ("Сбой разбора", "Parsing failure"),
        "lab.prompt.chartTitle": ("Все 8 сочетаний: выше точнее, правее дороже. Щёлкни по точке", "All 8 combinations: higher is more accurate, further right is costlier. Click a point"),
        "lab.gradGraph.title": ("Как градиент идёт назад", "How a gradient goes back"),
        "lab.gradGraph.subtitle": ("Нажимай «Шаг назад» и смотри, как градиент идёт от L к входам. Потом толкай входы кнопками плюс и минус: предсказание градиента сверяется с настоящим изменением.", "Press Step back and watch the gradient go from L to the inputs. Then push the inputs with the plus and minus buttons: the gradient's prediction is checked against the real change."),
        "lab.gradGraph.rule0": ("Прямой проход сделан: все значения посчитаны. Градиенты пока неизвестны.", "The forward pass is done: all values are computed. The gradients are not yet known."),
        "lab.gradGraph.rule1": ("Начало прохода назад: L по самому себе имеет градиент 1.", "The start of the backward pass: L by itself has gradient 1."),
        "lab.gradGraph.rule2": ("L это произведение суммы и f. Умножение: градиент суммы равен f, а градиент f равен сумме.", "L is the product of the sum and f. Multiplication: the sum's gradient equals f, and f's gradient equals the sum."),
        "lab.gradGraph.rule3": ("Сумма состоит из a · b и c. Сложение передаёт градиент как есть: обоим достаётся то же число.", "The sum consists of a · b and c. Addition passes the gradient as it is: both get the same number."),
        "lab.gradGraph.rule4": ("Снова умножение: градиент a это пришедшее число, умноженное на b; градиент b это оно же, умноженное на a. Больше всего L зависит от входа с самым большим числом.", "Multiplication again: a's gradient is the arriving number times b; b's gradient is the same number times a. L depends most on the input with the largest number."),
        "lab.gradGraph.step": ("Шаг назад", "Step back"),
        "lab.gradGraph.all": ("Весь проход", "The whole pass"),
        "lab.gradGraph.statNudges": ("Толчков", "Pushes"),
        "lab.gradGraph.statPredicted": ("Предсказал градиент", "The gradient predicted"),
        "lab.gradGraph.statReal": ("Изменилось на самом деле", "The real change"),
        "lab.gradGraph.challenge": ("Сделай L больше нуля, толкая входы на %@ не больше %@ раз. Сначала пройди назад и выбери вход с самым большим градиентом.", "Make L above zero by pushing inputs by %@ at most %@ times. First go back and pick the input with the largest gradient."),
        "lab.gradGraph.challengeDone": ("Есть! Градиент сразу показал самый сильный вход. Так обучение и выбирает, какие веса менять сильнее.", "Done! The gradient showed the strongest input at once. This is how training chooses which weights to change more."),
        "lab.gradGraph.howRules": ("Сложение передаёт градиент родителям как есть, а умножение передаёт его, умножив на другой множитель. После толчка числа новые, поэтому проход надо делать заново.", "Addition passes the gradient to the parents as it is, and multiplication passes it times the other factor. After a push the numbers are new, so the pass must be made again."),
        "lab.gradGraph.howPredict": ("Предсказание это градиент, умноженный на размер толчка. Здесь L линейна по каждому отдельному входу, поэтому оно совпадает точно. У настоящей сети формула кривая, и градиент точен только для маленьких шагов.", "The prediction is the gradient times the size of the push. Here L is linear in each single input, so it matches exactly. A real network's formula is curved, and a gradient is exact only for small steps."),
        "lab.bpe.title": ("Как рождаются токены", "How tokens are born"),
        "lab.bpe.subtitle": ("Сначала текст это байты. Жёлтым отмечена самая частая пара: нажми, и она станет одним токеном.", "At first a text is bytes. Yellow marks the most frequent pair: press, and it becomes one token."),
        "lab.bpe.tokensSpoken": ("Текст, разбитый на токены. Значение: сколько токенов сейчас.", "The text cut into tokens. The value: how many tokens there are now."),
        "lab.bpe.chartSpoken": ("Сколько токенов осталось после каждого слияния.", "How many tokens remain after each merge."),
        "lab.bpe.next": ("Следующая пара: %@ и %@, встречается %@ раз.", "The next pair: %@ and %@, occurring %@ times."),
        "lab.bpe.noPair": ("Пар, которые встречаются хотя бы дважды, больше нет.", "No pair occurs twice or more any longer."),
        "lab.bpe.merge": ("Слить пару", "Merge the pair"),
        "lab.bpe.mergeTen": ("10 слияний", "10 merges"),
        "lab.bpe.field": ("Свой текст", "Your own text"),
        "lab.bpe.use": ("Разбить", "Cut it"),
        "lab.bpe.statBytes": ("Байтов", "Bytes"),
        "lab.bpe.statTokens": ("Токенов", "Tokens"),
        "lab.bpe.statMerges": ("Слияний", "Merges"),
        "lab.bpe.statDecode": ("Текст восстановлен", "Text restored"),
        "lab.bpe.challenge": ("Сожми текст вдвое: токенов должно стать не больше половины байтов. Оранжевая линия на графике показывает эту половину.", "Compress the text by half: tokens must be at most half the bytes. The orange line on the chart shows this half."),
        "lab.bpe.challengeDone": ("Есть, за %@ слияний! Текст стал вдвое короче, а восстановить его можно точно.", "Done, in %@ merges! The text is half as long, and it can be restored exactly."),
        "lab.bpe.howBytes": ("Русская буква занимает два байта, а латинская один, поэтому русские буквы склеиваются первыми. Половина буквы показана шестнадцатеричным числом, например D0.", "A Russian letter takes two bytes and a Latin letter one, so Russian letters are glued first. Half a letter shows as a hexadecimal number, such as D0."),
        "lab.bpe.howLearned": ("Правила слияний выучиваются на тексте. На другом тексте те же правила сожмут его хуже, поэтому число токенов зависит от того, на чём учился токенизатор.", "The merge rules are learned from a text. On another text the same rules compress it worse, so the number of tokens depends on what the tokenizer learned from."),
        "lab.initHeat.title": ("Как сигнал идёт по слоям", "How a signal goes through the layers"),
        "lab.initHeat.subtitle": ("Двигай начальный масштаб весов и смотри на настоящие активации и градиенты сети из 8 слоёв до обучения.", "Move the starting weight scale and watch the real activations and gradients of an 8-layer network before training."),
        "lab.initHeat.heatTitle": ("Активации по слоям: столбец это слой, цвет показывает, сколько нейронов дали это значение", "Activations by layer: a column is a layer, colour shows how many neurons gave this value"),
        "lab.initHeat.gradTitle": ("Размер градиента по слоям", "Gradient size by layer"),
        "lab.initHeat.scale": ("Масштаб весов", "Weight scale"),
        "lab.initHeat.normalize": ("Нормализация слоя", "Layer normalization"),
        "lab.initHeat.statFirst": ("Разброс, 1-й слой", "Spread, layer 1"),
        "lab.initHeat.statLast": ("Разброс, 8-й слой", "Spread, layer 8"),
        "lab.initHeat.statGradFirst": ("Градиент, 1-й слой", "Gradient, layer 1"),
        "lab.initHeat.statGradLast": ("Градиент, 8-й слой", "Gradient, layer 8"),
        "lab.initHeat.challenge": ("Без нормализации сделай сеть здоровой: разброс в каждом слое от 0,2 до 0,9, а градиенты первого и последнего слоя различаются не больше чем втрое.", "Without normalization, make the network healthy: the spread in each layer from 0.2 to 0.9, and the gradients of the first and last layers differing at most threefold."),
        "lab.initHeat.challengeDone": ("Есть! Сигнал живёт во всех слоях. Теперь включи нормализацию и подвигай масштаб: столбцы перестанут меняться.", "Done! The signal lives in all layers. Now switch normalization on and move the scale: the columns stop changing."),
        "lab.initHeat.howHeat": ("Вес выбирается с разбросом масштаб / √32. Здоровый слой это широкое пятно посередине. Тонкая полоска у нуля значит, что сигнал погас, а пятна у +1 и −1 значат насыщение.", "A weight is chosen with the spread scale / √32. A healthy layer is a wide patch in the middle. A thin strip near zero means the signal has faded, and patches at +1 and −1 mean saturation."),
        "lab.initHeat.howNorm": ("Нормализация вычитает среднее и делит на разброс в каждом слое. Поэтому активации перестают зависеть от масштаба, но размер градиентов от него зависит.", "Normalization subtracts the mean and divides by the spread in each layer. So activations stop depending on the scale, but the size of gradients still depends on it."),
        "lab.opt.title": ("Гонка в длинной долине", "A race in a long valley"),
        "lab.opt.subtitle": ("Высота это настоящая ошибка. Нажми «Пуск» и смотри, как три правила катятся к дну. Двигай их шаги и крути долину мышью. Щелчок по поверхности задаёт новый старт.", "Height is the real error. Press Play and watch three rules roll to the bottom. Move their steps and turn the valley with the mouse. A click on the surface sets a new start."),
        "lab.opt.minimum": ("дно", "bottom"),
        "lab.opt.sceneLabel": ("Объёмная долина ошибки с тремя шариками. Значение: номер шага.", "A 3D error valley with three balls. The value: the step number."),
        "lab.opt.kind.plain": ("Обычный спуск", "Plain descent"),
        "lab.opt.kind.momentum": ("Импульс", "Momentum"),
        "lab.opt.kind.adam": ("Adam", "Adam"),
        "lab.opt.diverged": ("разошёлся", "diverged"),
        "lab.opt.steps": ("шагов: %@", "steps: %@"),
        "lab.opt.notReached": ("за %@ не дошёл", "not in %@"),
        "lab.opt.play": ("Пуск", "Play"),
        "lab.opt.pause": ("Пауза", "Pause"),
        "lab.opt.stepLine": ("Шаг %@ из %@", "Step %@ of %@"),
        "lab.opt.challenge": ("Сначала подними шаг обычного спуска выше 1 и посмотри, как он разойдётся. Затем добейся, чтобы обычный спуск дошёл быстрее 200 шагов, импульс быстрее 100, а Adam быстрее 30.", "First raise plain descent's step above 1 and see it diverge. Then get plain descent there in under 200 steps, momentum in under 100, and Adam in under 30."),
        "lab.opt.challengeDone": ("Есть! Обычному спуску мешает крутая стена, импульс копит скорость вдоль дна, а Adam выравнивает шаг по осям.", "Done! The steep wall holds plain descent back, momentum builds speed along the floor, and Adam evens out the step across axes."),
        "lab.opt.howValley": ("Рельеф: 0,005x² + y². Шарик идёт вниз, пока ошибка не станет меньше 0,01. Числа шагов считаются за 1500 шагов по тем же формулам, что в программе, а анимация показывает первые 200.", "The relief: 0.005x² + y². A ball goes down until the error falls below 0.01. Step counts are computed over 1500 steps by the same formulas as in the program, and the animation shows the first 200."),
        "lab.opt.howRules": ("По крутой оси обычный спуск умножает y на 1 − 2 · шаг, поэтому шаг больше 1 расходится. Импульс усредняет градиенты, а Adam делит шаг по каждой оси на её типичный градиент. Это игрушка в двух измерениях: выводы о настоящих сетях из неё не следуют.", "On the steep axis plain descent multiplies y by 1 − 2 · step, so a step above 1 diverges. Momentum averages gradients, and Adam divides the step on each axis by its typical gradient. This is a toy in two dimensions: conclusions on real networks do not follow from it."),
        "lab.doctor.title": ("Доктор обучения", "The training doctor"),
        "lab.doctor.subtitle": ("Перед тобой настоящие запуски одной сети, и у каждого своя беда. По кривым поставь диагноз.", "Here are real runs of one network, each with its own trouble. Diagnose them from the curves."),
        "lab.doctor.patient": ("Пациент %@ из %@", "Patient %@ of %@"),
        "lab.doctor.train": ("обучение", "training"),
        "lab.doctor.check": ("проверка", "check"),
        "lab.doctor.epochs": ("эпохи", "epochs"),
        "lab.doctor.error": ("ошибка", "error"),
        "lab.doctor.diagnosis.healthy": ("Здоров", "Healthy"),
        "lab.doctor.diagnosis.rate_high": ("Шаг слишком большой", "Step too large"),
        "lab.doctor.diagnosis.rate_low": ("Шаг слишком маленький", "Step too small"),
        "lab.doctor.diagnosis.labels_shuffled": ("Перепутаны ответы", "Answers mixed up"),
        "lab.doctor.diagnosis.wrong_sign": ("Перепутан знак", "Sign reversed"),
        "lab.doctor.diagnosis.too_little_data": ("Мало данных", "Too little data"),
        "lab.doctor.why.healthy": ("Верно. Обе кривые падают, проверочная чуть выше: так и должно быть.", "Right. Both curves fall, the check one a little higher: just as it should be."),
        "lab.doctor.why.rate_high": ("Верно. Ошибка взлетает в первые же эпохи и застывает: шаг перепрыгивает долину.", "Right. The error flies up in the first epochs and freezes: the step jumps over the valley."),
        "lab.doctor.why.rate_low": ("Верно. Сломанного нет, но кривая почти лежит: так учиться можно почти вечно.", "Right. Nothing is broken, but the curve almost lies flat: training this way could take nearly forever."),
        "lab.doctor.why.labels_shuffled": ("Верно. Обе кривые стоят у ln 2: между точкой и ответом нет связи, и выучить нечего.", "Right. Both curves stand near ln 2: no link exists between a point and its answer, so there is nothing to learn."),
        "lab.doctor.why.wrong_sign": ("Верно. Начало нормальное, но дальше сеть идёт в гору, а не под гору.", "Right. The start is normal, but then the network goes uphill, not downhill."),
        "lab.doctor.why.too_little_data": ("Верно. Обучающая ошибка падает до нуля, а проверочная растёт: это переобучение.", "Right. The training error falls to zero and the check error grows: this is overfitting."),
        "lab.doctor.tryAgain": ("Не то. Посмотри, куда идёт каждая кривая и где она начинается.", "Not that. Look where each curve goes and where it starts."),
        "lab.doctor.compare": ("Показать здоровые кривые", "Show the healthy curves"),
        "lab.doctor.next": ("Следующий пациент", "Next patient"),
        "lab.doctor.statDone": ("Вылечено", "Treated"),
        "lab.doctor.statFirst": ("С первого раза", "At the first try"),
        "lab.doctor.statStart": ("Начальная ошибка", "Starting error"),
        "lab.doctor.challenge": ("Поставь верный диагноз всем шести пациентам.", "Give the right diagnosis to all six patients."),
        "lab.doctor.challengeDone": ("Есть! Помни: диагноз по кривым это гипотеза. Проверяй её, меняя по одной вещи за раз.", "Done! Remember: a diagnosis from curves is a hypothesis. Test it by changing one thing at a time."),
        "lab.doctor.howChecks": ("Пунктир это ln 2 ≈ 0,693, ошибка случайного угадывания в задаче с двумя классами. С него и должна начинаться кривая. Если сеть не может заучить даже маленький пакет, ошибка в программе или в данных.", "The dashed line is ln 2 ≈ 0.693, the error of random guessing in a two-class task. The curve should start there. If a network cannot memorize even a small batch, the bug is in the program or the data."),
        "lab.doctor.howReal": ("Все кривые это настоящие запуски программы из урока на чистом Python, с одной поломкой в каждом. Они записаны каждые 10 эпох.", "All curves are real runs of the lesson's plain Python program, with one fault in each. They were recorded every 10 epochs."),
        "lab.doctor.chartSpoken": ("Кривые ошибки на обучении и на проверке. Значение: начальная ошибка и две конечные.", "Error curves on training and check data. The value: the starting error and the two final ones."),
        "lab.bandit.title": ("Пять автоматов", "Five slot machines"),
        "lab.bandit.subtitle": ("Жми на автомат и тяни его рычаг. Столбик это твоя оценка, а настоящие вероятности спрятаны. Ниже настоящие кривые сожаления за 3000 ходов.", "Click a machine to pull its lever. The bar is your estimate, and the real probabilities are hidden. Below are real regret curves over 3000 turns."),
        "lab.bandit.reveal": ("Показать настоящие вероятности", "Show the real probabilities"),
        "lab.bandit.newGame": ("Новая игра", "New game"),
        "lab.bandit.statPulls": ("Ходов", "Turns"),
        "lab.bandit.statWins": ("Выигрышей", "Wins"),
        "lab.bandit.statRegret": ("Сожаление", "Regret"),
        "lab.bandit.epsilon": ("ε =", "ε ="),
        "lab.bandit.greedy": ("жадное", "greedy"),
        "lab.bandit.yourRule": ("твоё ε", "your ε"),
        "lab.bandit.final": ("сожаление за 3000: %@", "regret over 3000: %@"),
        "lab.bandit.times": ("×%@", "×%@"),
        "lab.bandit.armSpoken": ("Автомат %@", "Machine %@"),
        "lab.bandit.turns": ("ходы", "turns"),
        "lab.bandit.regretAxis": ("сожаление", "regret"),
        "lab.bandit.chartSpoken": ("Кривые сожаления трёх правил. Значение: сожаление твоего правила за 3000 ходов.", "Regret curves of three rules. The value: your rule's regret over 3000 turns."),
        "lab.bandit.challenge": ("Сыграй сам 30 ходов так, чтобы сожаление было меньше 6: наугад вышло бы около 9. Затем подбери ε, при котором сожаление за 3000 ходов меньше 115.", "Play 30 turns yourself with regret below 6: guessing would give about 9. Then find ε for which regret over 3000 turns is below 115."),
        "lab.bandit.challengeDone": ("Есть! Ты пробовал и остановился на лучшем, а ε нашёл между двумя крайностями: без пробы застрянешь, с лишней пробой потеряешь.", "Done! You tried and settled on the best, and found ε between two extremes: without trying you get stuck, with too much you lose."),
        "lab.bandit.howRegret": ("Сожаление считается по настоящим вероятностям: за каждый ход прибавляется 0,8 минус вероятность выбранного автомата. Само число выигрышей шумит сильнее, поэтому его не сравнивают.", "Regret uses the real probabilities: each turn adds 0.8 minus the chosen machine's probability. The number of wins itself is noisier, so it is not compared."),
        "lab.bandit.howReal": ("Кривые это среднее по 100 настоящим запускам той же программы, что в уроке, с теми же зёрнами случайности.", "The curves are means over 100 real runs of the lesson's program, with the same random seeds."),
        "lab.mdp.title": ("Поверхность ценности", "The value surface"),
        "lab.mdp.subtitle": ("Высота башни это настоящая ценность клетки. Конусы показывают политику, белая линия это маршрут от S. Жми «Один проход» и крути сцену мышью.", "A tower's height is the cell's real value. Cones show the policy, and the white line is the route from S. Press One sweep and turn the scene with the mouse."),
        "lab.mdp.start": ("S", "S"),
        "lab.mdp.goal": ("цель", "goal"),
        "lab.mdp.pit": ("яма", "pit"),
        "lab.mdp.sceneLabel": ("Объёмная поверхность ценности клетчатого мира. Значение: ценность старта.", "A 3D value surface of the grid world. The value: the start's value."),
        "lab.mdp.oneSweep": ("Один проход", "One sweep"),
        "lab.mdp.play": ("Пуск", "Play"),
        "lab.mdp.pause": ("Пауза", "Pause"),
        "lab.mdp.toEnd": ("До конца", "To the end"),
        "lab.mdp.reset": ("Сброс", "Reset"),
        "lab.mdp.slip": ("Проскальзывание", "Slip"),
        "lab.mdp.gamma": ("Скидка γ", "Discount γ"),
        "lab.mdp.waiting": ("Агент упирается в стену и ждёт, когда его снесёт: идти вверх рискованнее. Это лучшая политика в этой модели, а не ошибка.", "The agent presses against the wall, waiting to be carried: going up is riskier. This is the best policy in this model, not a bug."),
        "lab.mdp.statSweeps": ("Проходов", "Sweeps"),
        "lab.mdp.statValue": ("Ценность старта", "Start's value"),
        "lab.mdp.statRoute": ("Шагов по стрелкам", "Steps by arrows"),
        "lab.mdp.challenge": ("Сделай три прохода по одному и проследи за волной от цели. Затем дойди до конца и подбери проскальзывание, при котором маршрут уходит от края ямы, но агент не замирает у стены.", "Do three sweeps one at a time and follow the wave from the goal. Then go to the end and find a slip at which the route moves away from the pit's edge, yet the agent does not freeze at the wall."),
        "lab.mdp.challengeDone": ("Есть! Осторожность никто не программировал: она вышла из формулы, потому что яма снижает ценность соседних клеток.", "Done! Nobody programmed the caution: it came from the formula, because the pit lowers the value of neighbouring cells."),
        "lab.mdp.howHeight": ("Высота равна V: от −1 у самых плохих клеток до +1 у цели. У самой цели и ямы в формуле ценность 0, игра там окончена, поэтому в сцене для них показана награда за вход.", "Height equals V: from −1 at the worst cells to +1 at the goal. By the formula the goal and pit themselves have value 0, as the game is over there, so the scene shows their entry reward."),
        "lab.mdp.howSlip": ("Проскальзывание делится поровну на две стороны. Шаг стоит −0,04, цель +1, яма −1. Эти числа выбрал я, при других граница поведения сдвинется.", "Slip is split equally between two sides. A step costs −0.04, the goal +1, the pit −1. I chose these numbers, and with others the boundary of behaviour moves."),
        "lab.qmaze.title": ("Агент учится сам", "An agent learns on its own"),
        "lab.qmaze.subtitle": ("Белый кружок это агент. Цветной треугольник в клетке это Q этого действия: зелёный хорошо, красный плохо. Нажми «Пуск» или промотай обучение. Щелчок ставит и убирает стену.", "The white dot is the agent. A coloured triangle in a cell is that action's Q: green is good, red is bad. Press Play or fast-forward training. A click places or removes a wall."),
        "lab.qmaze.play": ("Пуск", "Play"),
        "lab.qmaze.pause": ("Пауза", "Pause"),
        "lab.qmaze.hundred": ("+100 игр", "+100 games"),
        "lab.qmaze.reset": ("Забыть всё", "Forget everything"),
        "lab.qmaze.rule": ("Правило", "Rule"),
        "lab.qmaze.statGames": ("Игр", "Games"),
        "lab.qmaze.statRoute": ("Шагов без случайности", "Steps without randomness"),
        "lab.qmaze.statShortest": ("Кратчайший путь", "Shortest path"),
        "lab.qmaze.statStart": ("Лучшее Q на старте", "Best Q at start"),
        "lab.qmaze.gamesAxis": ("игры", "games"),
        "lab.qmaze.returnAxis": ("награда за игру", "reward per game"),
        "lab.qmaze.boardSpoken": ("Поле агента с цветными оценками действий. Значение: сыгранные игры.", "The agent's field with coloured action estimates. The value: games played."),
        "lab.qmaze.chartSpoken": ("Кривая средней награды за игру.", "A curve of mean reward per game."),
        "lab.qmaze.challenge": ("Обучи агента. Затем щелчком поставь стену прямо над ямой, чтобы старый путь закрылся, и обучай дальше, пока шагов без случайности не станет столько же, сколько в кратчайшем пути.", "Train the agent. Then click to place a wall right above the pit, closing the old path, and keep training until the steps without randomness equal the shortest path."),
        "lab.qmaze.challengeDone": ("Есть! Агент не знает карту. Он нашёл обход только потому, что упёрся в стену и его оценки изменились.", "Done! The agent does not know the map. It found the way round only because it hit the wall and its estimates changed."),
        "lab.qmaze.howColors": ("Четыре треугольника в клетке соответствуют четырём действиям. Сила цвета это размер Q. Стрелка показывает лучшее действие. Там, где агент не бывает, цвета так и остаются бледными.", "The four triangles in a cell match four actions. Colour strength is the size of Q. The arrow shows the best action. Where the agent does not go, the colours stay pale."),
        "lab.qmaze.howRules": ("Q-обучение смотрит на лучшее следующее действие, а SARSA на выбранное. Подними ε и сравни, как далеко от ямы держится каждое правило. Первый запуск совпадает с программой урока.", "Q-learning looks at the best next action, and SARSA at the chosen one. Raise ε and compare how far from the pit each rule stays. The first run matches the lesson's program."),
        "lab.corridor.title": ("Коридор с перепутанными кнопками", "A corridor with swapped buttons"),
        "lab.corridor.subtitle": ("Агент не видит, где он, и жмёт «вправо» с вероятностью p. В клетке 2 кнопки перепутаны. Тащи оранжевую точку по кривой ценности, затем запусти обучение: белая точка это его политика.", "The agent cannot see where it is and presses right with probability p. In cell 2 the buttons are swapped. Drag the orange point along the value curve, then run training: the white point is its policy."),
        "lab.corridor.rate": ("шаг 2^%@", "step 2^%@"),
        "lab.corridor.baseline": ("Базовая линия", "Baseline"),
        "lab.corridor.train": ("Обучить", "Train"),
        "lab.corridor.button": ("«вправо» ведёт", "right leads"),
        "lab.corridor.corridorSpoken": ("Коридор из трёх клеток и выхода. Во второй клетке кнопки перепутаны.", "A corridor of three cells and an exit. In the second cell the buttons are swapped."),
        "lab.corridor.pAxis": ("вероятность p", "probability p"),
        "lab.corridor.valueAxis": ("ценность", "value"),
        "lab.corridor.valueSpoken": ("Кривая ценности политики, точка перетаскивается. Значение: вероятность p.", "The policy's value curve, with a draggable point. The value: probability p."),
        "lab.corridor.gamesAxis": ("партии", "games"),
        "lab.corridor.returnAxis": ("отдача", "return"),
        "lab.corridor.returnSpoken": ("Кривая отдачи за партию.", "A curve of return per game."),
        "lab.corridor.statHand": ("Твоё p", "Your p"),
        "lab.corridor.statValue": ("Ценность твоего p", "Value of your p"),
        "lab.corridor.statPolicy": ("p у обучения", "p of training"),
        "lab.corridor.statGames": ("Партий", "Games"),
        "lab.corridor.challenge": ("Сначала сам найди вершину кривой. Затем добейся, чтобы обучение вышло к вершине. Затем поставь шаг 2^−9 или больше без базовой линии и посмотри, как p застынет на краю.", "First find the top of the curve yourself. Then get training to reach the top. Then set step 2^−9 or larger without a baseline and watch p freeze at the edge."),
        "lab.corridor.challengeDone": ("Есть! Лучшая политика здесь случайна, поэтому её нашёл только градиент политики. А большой шаг выбил её туда, где градиент равен нулю.", "Done! The best policy here is random, so only a policy gradient found it. And a large step knocked it to where the gradient is zero."),
        "lab.corridor.howValue": ("Кривая это точная формула −2(2 − p) / (p(1 − p)). Вершина при p = 2 − √2 ≈ 0,586, значение около −11,66. Зелёный пунктир это вершина.", "The curve is the exact formula −2(2 − p) / (p(1 − p)). The top is at p = 2 − √2 ≈ 0.586, with a value near −11.66. The green dashes mark the top."),
        "lab.corridor.howRun": ("Обучение начинается с p = 0,1 и идёт 600 партий по формуле из урока. Каждый запуск со своим зерном случайности, поэтому кривые различаются. Партия обрывается на 500 шагах.", "Training starts at p = 0.1 and runs 600 games by the lesson's formula. Each run has its own random seed, so curves differ. A game stops at 500 steps."),
        "lab.fine.title": ("Дообучить или учить заново", "Fine-tune or train anew"),
        "lab.fine.subtitle": ("Настоящие кривые программы урока: ошибка на новом стиле за 900 шагов. Выбирай способ, двигай бюджет весов и смотри, что остаётся.", "Real curves from the lesson's program: the error on the new style over 900 steps. Pick a method, move the weight budget and see what remains."),
        "lab.fine.data": ("Предложений нового стиля", "Sentences of the new style"),
        "lab.fine.budget": ("Весов не больше %@", "At most %@ weights"),
        "lab.fine.scratch": ("С нуля", "From scratch"),
        "lab.fine.all": ("Все веса", "All weights"),
        "lab.fine.last": ("Последний слой", "Last layer"),
        "lab.fine.adapterOff": ("Выключить адаптер", "Switch the adapter off"),
        "lab.fine.statLoss": ("Ошибка в конце", "Final error"),
        "lab.fine.statWeights": ("Обучаемых весов", "Trainable weights"),
        "lab.fine.statBest": ("Лучшее в бюджете", "Best in budget"),
        "lab.fine.steps": ("шаги", "steps"),
        "lab.fine.lossAxis": ("ошибка", "error"),
        "lab.fine.chartSpoken": ("Кривые ошибки разных способов дообучения.", "Error curves of different fine-tuning methods."),
        "lab.fine.challenge": ("Поставь бюджет не больше 250 весов, выбери лучший способ в этом бюджете и выключи его адаптер: ошибка должна вернуться к исходной.", "Set a budget of at most 250 weights, pick the best method within it, and switch its adapter off: the error should return to the original."),
        "lab.fine.challengeDone": ("Есть! Адаптер обгоняет обучение с нуля малым числом весов и не трогает исходную модель. Цена: качество ниже, чем при дообучении всех весов.", "Done! An adapter beats training from scratch with few weights and leaves the original model untouched. The price: quality below fine-tuning all weights."),
        "lab.fine.howCurves": ("Пунктир это случайное угадывание, ln 29. Все дообучения начинаются с ошибки 3,451: готовая модель уверенно ошибается на новом стиле. Кривые считались по 300 шагов.", "The dashes are random guessing, ln 29. All fine-tuning starts at error 3.451: the ready model is confidently wrong on the new style. Curves were computed every 300 steps."),
        "lab.fine.howLora": ("Текст снизу записан один раз для 80 предложений. Адаптер здесь только на последнем слое, настоящая LoRA ставит их на многие слои.", "The text below was recorded once for 80 sentences. The adapter here sits only on the last layer; real LoRA puts them on many layers."),
        "lab.rlhf.title": ("Ты учишь модель", "You teach the model"),
        "lab.rlhf.subtitle": ("Выбери лучшее предложение в каждой паре. По твоим выборам обучится модель награды, а маленькая языковая модель сдвинется в её сторону. Всё считается прямо здесь.", "Choose the better sentence in each pair. A reward model trains on your choices, and a small language model shifts towards it. Everything is computed right here."),
        "lab.rlhf.progress": ("Пара %@ из %@", "Pair %@ of %@"),
        "lab.rlhf.auto": ("Выбрать за меня по правилу из урока", "Choose for me by the lesson's rule"),
        "lab.rlhf.penalty": ("Штраф за отход от исходной модели", "Fine for leaving the original model"),
        "lab.rlhf.step": ("шаг %@", "step %@"),
        "lab.rlhf.statReward": ("Средняя награда", "Mean reward"),
        "lab.rlhf.statDifferent": ("Разных предложений", "Different sentences"),
        "lab.rlhf.statLength": ("Средняя длина", "Mean length"),
        "lab.rlhf.learned": ("Что выучила модель награды: самые любимые и нелюбимые слова", "What the reward model learned: the most and least liked words"),
        "lab.rlhf.stepsAxis": ("шаги сдвига", "shift steps"),
        "lab.rlhf.axis": ("награда и разнообразие", "reward and variety"),
        "lab.rlhf.chartSpoken": ("Кривые награды и числа разных предложений по шагам сдвига.", "Curves of reward and the number of different sentences by shift steps."),
        "lab.rlhf.challenge": ("Без штрафа дойди до конца ползунка и найди поломку: разных предложений остаётся мало. Затем включи штраф, дойди до конца и убедись, что модель уцелела.", "Without the fine go to the slider's end and find the breakdown: few different sentences remain. Then switch the fine on, go to the end and check that the model survived."),
        "lab.rlhf.challengeDone": ("Есть! Награда росла, пока модель не нашла лазейку. Штраф не даёт уйти так далеко, и это главный урок RLHF.", "Done! Reward grew until the model found a loophole. The fine prevents going so far, and that is RLHF's main lesson."),
        "lab.rlhf.howReward": ("Модель награды это вес у каждого слова, а награда предложения это сумма весов. Обучается на парах: вероятность выбора равна 1 / (1 + e^(R₂ − R₁)). Порядок слов и повторы она не видит.", "The reward model is a weight per word, and a sentence's reward is the sum. It trains on pairs: the choice's probability is 1 / (1 + e^(R₂ − R₁)). It sees neither word order nor repeats."),
        "lab.rlhf.howShift": ("Сдвиг это REINFORCE на строках таблицы пар слов: 2000 шагов. Синяя кривая это награда, растянутая на высоту графика, а оранжевая это доля разных предложений из 300.", "The shift is REINFORCE on the rows of the word-pair table: 2000 steps. The blue curve is reward, stretched to the chart's height, and the orange one is the share of different sentences of 300."),
        "lab.winner.title": ("Проклятие победителя", "The winner's curse"),
        "lab.winner.subtitle": ("Каждая точка это модель, и все они верны ровно в 70 % случаев: это зелёный пунктир. Оранжевая точка это победитель на тесте. Зелёная внизу это он же на свежем тесте.", "Each dot is a model, all of them exactly 70 % right: the green dashes. The orange dot is the winner on the test. The green one below is the same winner on a fresh test."),
        "lab.winner.models": ("Моделей: %@", "Models: %@"),
        "lab.winner.size": ("Вопросов: %@", "Questions: %@"),
        "lab.winner.again": ("Новый опыт", "New experiment"),
        "lab.winner.statWinner": ("Победитель на тесте", "Winner on the test"),
        "lab.winner.statFresh": ("Он же на свежем тесте", "Same on a fresh test"),
        "lab.winner.statInflation": ("Завышение в среднем", "Mean inflation"),
        "lab.winner.axis": ("доля верных ответов", "share of right answers"),
        "lab.winner.chartSpoken": ("Точки моделей по доле верных ответов. Значение: результат победителя.", "Model dots by share of right answers. The value: the winner's result."),
        "lab.winner.challenge": ("Поставь не меньше 100 моделей и подбери такой размер теста, чтобы среднее завышение стало меньше 4 пунктов.", "Set at least 100 models and find a test size at which the mean inflation is below 4 points."),
        "lab.winner.challengeDone": ("Есть! Заметь, сколько вопросов на это ушло. Вот почему 2 пункта разницы на маленьком тесте почти ничего не значат.", "Done! Notice how many questions that took. That is why a 2-point difference on a small test means almost nothing."),
        "lab.winner.howDots": ("Высота точки ничего не значит, она только разводит точки. Все модели одинаковы, поэтому весь разброс здесь это шум теста.", "A dot's height means nothing and only spreads the dots out. All models are the same, so all the spread here is test noise."),
        "lab.winner.howMean": ("Завышение считается по 40 повторам всего опыта: среднее лучшей оценки минус 70 %. Опыт считается прямо сейчас, каждая модель отвечает на все вопросы.", "Inflation is computed over 40 repeats of the whole experiment: the mean best score minus 70 %. The experiment runs right now, with each model answering all questions."),
        "lab.probe.title": ("Раздели активации сам", "Split the activations yourself"),
        "lab.probe.subtitle": ("Точки это настоящие активации сети в двух главных направлениях. Оранжевые отвечают на вопрос «да». Тащи концы прямой и раздели цвета: это и есть зонд, только в двух измерениях.", "Dots are the network's real activations along two main directions. Orange ones answer the question with yes. Drag the line's ends and split the colours: that is a probe, only in two dimensions."),
        "lab.probe.question": ("Вопрос", "Question"),
        "lab.probe.q.next_space": ("Сейчас кончится слово?", "Does a word end next?"),
        "lab.probe.q.last_vowel": ("Последняя буква гласная?", "Is the last letter a vowel?"),
        "lab.probe.q.third_word": ("Идёт третье слово?", "Is this the third word?"),
        "lab.probe.untrained": ("Необученная сеть", "Untrained network"),
        "lab.probe.statLine": ("Твоя прямая", "Your line"),
        "lab.probe.statFull": ("Зонд на 24 числах", "Probe on 24 numbers"),
        "lab.probe.statAlways": ("Всегда один ответ", "Always one answer"),
        "lab.probe.plotSpoken": ("Точки активаций и прямая с двумя перетаскиваемыми концами. Значение: точность прямой.", "Activation dots and a line with two draggable ends. The value: the line's accuracy."),
        "lab.probe.challenge": ("На обученной сети для вопроса о конце слова добейся точности прямой не ниже 0,97. Затем включи необученную сеть и посмотри, что с точками.", "On the trained network, for the word-end question, get your line's accuracy to at least 0.97. Then switch on the untrained network and see what happens to the dots."),
        "lab.probe.challengeDone": ("Есть! И всё же зонд на необученной сети тоже намного лучше простого ответа. Поэтому сравнивай с контролем, а понять, использует ли сеть эти сведения, поможет только удаление направления.", "Done! Yet a probe on the untrained network also far beats a plain answer. So compare with a control, and only removing the direction helps tell whether the network uses this information."),
        "lab.probe.howPoints": ("Показана часть настоящих точек из программы урока. Направления найдены методом главных компонент отдельно для каждой сети, поэтому картинки разные.", "A part of the real points from the lesson's program is shown. Directions come from principal components, separately for each network, so the pictures differ."),
        "lab.probe.howFull": ("Зонд на 24 числах это логистическая регрессия на всех активациях, точность на отложенной четверти. Твоя прямая видит только два числа, поэтому иногда хуже.", "The probe on 24 numbers is logistic regression on all activations, with accuracy on a held-out quarter. Your line sees only two numbers, so it is sometimes worse."),
        "lab.super.title": ("Больше понятий, чем измерений", "More features than dimensions"),
        "lab.super.subtitle": ("Сеть учится прямо сейчас по формулам урока: сжать признаки в 2 или 3 числа и вернуть обратно. Двигай редкость и смотри, что соберётся из векторов.", "The network is training right now by the lesson's formulas: squeeze features into 2 or 3 numbers and bring them back. Move the sparsity and see what forms from the vectors."),
        "lab.super.shape": ("Форма", "Shape"),
        "lab.super.flat": ("5 признаков в 2 числах", "5 features in 2 numbers"),
        "lab.super.solid": ("6 признаков в 3 числах", "6 features in 3 numbers"),
        "lab.super.again": ("Заново", "Again"),
        "lab.super.sparsity": ("Редкость %@", "Sparsity %@"),
        "lab.super.statAlive": ("Живых признаков", "Live features"),
        "lab.super.statStep": ("Шаг обучения", "Training step"),
        "lab.super.statLongest": ("Самый длинный вектор", "Longest vector"),
        "lab.super.sceneSpoken": ("Объёмная фигура из векторов признаков. Значение: число живых признаков.", "A solid figure of feature vectors. The value: the number of live features."),
        "lab.super.planeSpoken": ("Векторы признаков на плоскости. Значение: число живых признаков.", "Feature vectors on a plane. The value: the number of live features."),
        "lab.super.challenge": ("Найди редкость, при которой на плоскости живы все 5 признаков и видна фигура. Затем получи всех 6 живых в объёме и покрути фигуру мышью.", "Find the sparsity at which all 5 features are alive on the plane and a figure shows. Then get all 6 alive in 3D and turn the figure with the mouse."),
        "lab.super.challengeDone": ("Есть! Пятиугольник и октаэдр никто не задавал. Веса сошлись к ним сами, потому что так помеха от редких признаков меньше всего.", "Done! Nobody specified the pentagon and the octahedron. The weights reached them by themselves, because that minimizes interference from sparse features."),
        "lab.super.howModel": ("Выход равен ReLU(Wᵀ · W · x + b). Столбец W это вектор признака, круг это длина 1. Живым считается вектор длиннее 0,5.", "The output is ReLU(Wᵀ · W · x + b). A column of W is a feature's vector, and the circle is length 1. A vector longer than 0.5 counts as alive."),
        "lab.super.howLive": ("Обучение идёт 4000 шагов и начинается заново при каждой смене редкости. Результат зависит от случайного начала: если вектор отстал, нажми «Заново». В объёме тонкие линии соединяют близкие концы.", "Training runs 4000 steps and restarts at each sparsity change. The result depends on the random start: if a vector lags, press Again. In 3D thin lines join nearby tips."),
        "lab.reason.title": ("Что стоит рассуждение", "What reasoning costs"),
        "lab.reason.subtitle": ("Настоящие результаты qwen3.5. Полоска это число токенов рассуждения на задаче: зелёная верно, красная неверно или без ответа. Значок справа показывает ответ сразу. Тащи синюю линию лимита.", "Real qwen3.5 results. A bar is the reasoning's token count on a task: green is right, red is wrong or unanswered. The mark on the right shows the immediate answer. Drag the blue limit line."),
        "lab.reason.statLimit": ("Лимит токенов", "Token limit"),
        "lab.reason.statReason": ("Верно с рассуждением", "Right with reasoning"),
        "lab.reason.statDirect": ("Верно сразу", "Right at once"),
        "lab.reason.price": ("Цена 1000 токенов %@", "Price of 1000 tokens %@"),
        "lab.reason.tokens": ("токены рассуждения", "reasoning tokens"),
        "lab.reason.steps": ("шаги обучения", "training steps"),
        "lab.reason.share": ("доля рассуждения", "share of reasoning"),
        "lab.reason.barsSpoken": ("Полоски токенов по задачам с линией лимита. Значение: лимит.", "Token bars by task with a limit line. The value: the limit."),
        "lab.reason.chartSpoken": ("Как обучается выбор. Значение: итоговая доля рассуждения.", "How the choice trains. The value: the final share of reasoning."),
        "lab.reason.challenge": ("Найди цену, при которой выбор почти всегда рассуждает, и цену, при которой почти никогда. Затем подбери лимит меньше 2200 токенов, при котором решено не меньше 8 задач.", "Find a price at which the choice nearly always reasons, and one at which it nearly never does. Then find a limit under 2200 tokens at which at least 8 tasks are solved."),
        "lab.reason.challengeDone": ("Есть! Рассуждение окупается, только пока токены дёшевы, а задачи трудны. Перелом около 0,22, как и в расчёте урока.", "Done! Reasoning pays only while tokens are cheap and tasks are hard. The turning point is near 0.22, as in the lesson's calculation."),
        "lab.reason.howBars": ("Опыт шёл с лимитом 3000 токенов. Две полоски упёрлись в него и остались без ответа. Более низкий лимит здесь посчитан по записи: задача считается решённой, если на неё ушло не больше токенов.", "The experiment had a 3000-token limit. Two bars hit it and stayed unanswered. A lower limit here is computed from the recording: a task counts as solved if it took no more tokens."),
        "lab.reason.howPrice": ("Обучается только выбор режима по формуле REINFORCE, а модель не меняется. Награда равна 1 за верный ответ минус цена токенов. Это учебная игрушка, настоящий RLVR сдвигает сами токены.", "Only the mode choice trains, by the REINFORCE formula, and the model does not change. The reward is 1 for a right answer minus the token price. This is a teaching toy; real RLVR shifts the tokens themselves."),
        "lab.search.title": ("Что найдёт поиск", "What the search finds"),
        "lab.search.subtitle": ("Настоящие близости bge-m3 на заметках урока. Выбирай вопрос и способ, двигай число кусков. Зелёный кусок из верной заметки, слева его близость. Показаны первые семь.", "Real bge-m3 closeness on the lesson's notes. Pick a question and a method, move the number of chunks. A green chunk is from the right note, with its closeness on the left. The first seven are shown."),
        "lab.search.question": ("Вопрос", "Question"),
        "lab.search.method": ("Способ", "Method"),
        "lab.search.vector": ("Векторы", "Vectors"),
        "lab.search.words": ("Слова", "Words"),
        "lab.search.both": ("Смесь", "Mix"),
        "lab.search.k": ("Кусков: %@", "Chunks: %@"),
        "lab.search.statFound": ("Доля найденных ответов", "Share of answers found"),
        "lab.search.statMrr": ("MRR", "MRR"),
        "lab.search.statDone": ("Решено способов", "Methods done"),
        "lab.search.challenge": ("Для каждого из трёх способов найди наименьшее число кусков, при котором найдены все 9 ответов.", "For each of the three methods, find the smallest number of chunks at which all 9 answers are found."),
        "lab.search.challengeDone": ("Есть! Векторам хватило 5 кусков, смеси 8, а словам 16. Чем больше кусков, тем больше мусора получит модель, поэтому меряй поиск отдельно от ответов.", "Done! Vectors needed 5 chunks, the mix 8, and words 16. The more chunks, the more junk the model gets, so measure search apart from answers."),
        "lab.search.howClose": ("Близость это косинус между векторами вопроса и куска. Способ со словами считает общие слова, а смесь складывает 1 / (60 + место) из двух списков.", "Closeness is the cosine between the question's and the chunk's vectors. The words method counts shared words, and the mix adds 1 / (60 + place) from the two lists."),
        "lab.search.howFound": ("Ответ считается найденным, если кусок из верной заметки попал в первые куски. Вопросов всего 9, поэтому числа грубые.", "An answer counts as found if a chunk from the right note is among the first chunks. There are only 9 questions, so the numbers are rough."),
        "lab.agent.title": ("Разбор агента", "Inspecting an agent"),
        "lab.agent.subtitle": ("Настоящие записи агента на qwen2.5-coder:7b. Иди по шагам: синее пишет модель, оранжевое возвращает твоя программа. Где задача не решена, поставь диагноз.", "Real recordings of an agent on qwen2.5-coder:7b. Step through: blue is written by the model, orange is returned by your program. Where a task failed, give a diagnosis."),
        "lab.agent.task": ("Задача", "Task"),
        "lab.agent.next": ("Следующий шаг", "Next step"),
        "lab.agent.right": ("Ответ верен", "The answer is right"),
        "lab.agent.wrong": ("Ответ неверен", "The answer is wrong"),
        "lab.agent.diagnosis.computed_itself": ("Посчитала сама и ошиблась", "Computed by itself and erred"),
        "lab.agent.diagnosis.forgot_part": ("Забыла часть вопроса", "Forgot part of the question"),
        "lab.agent.diagnosis.gave_up": ("Сдалась, не вызвав инструмент", "Gave up without calling a tool"),
        "lab.agent.statSolved": ("Решено задач", "Tasks solved"),
        "lab.agent.statDiagnosed": ("Поставлено диагнозов", "Diagnoses given"),
        "lab.agent.challenge": ("Пройди все задачи и поставь верный диагноз трём неудачам.", "Go through all tasks and give the right diagnosis to the three failures."),
        "lab.agent.challengeDone": ("Есть! Агент ни разу не нарушил формат, но ошибся по существу. Поэтому нужна проверка ответа, а не только разбор строки.", "Done! The agent never broke the format but erred in substance. So you need to check the answer, not only parse the line."),
        "lab.agent.howLoop": ("Цикл: отправить разговор, найти в ответе строку действия, выполнить инструмент своим кодом, вернуть результат. Не больше 6 шагов.", "The loop: send the conversation, find an action line in the reply, run the tool with your own code, return the result. At most 6 steps."),
        "lab.agent.howReal": ("Это запись одного запуска с нулевой температурой, а не живая модель. Запусти программу урока и получишь свежий результат.", "This is a recording of one run at zero temperature, not a live model. Run the lesson's program for a fresh result."),
        "lab.boat.title": ("Лодка и монеты", "The boat and the coins"),
        "lab.boat.subtitle": ("Агент учится Q-обучением прямо сейчас. Наша цель финиш, но монеты тоже приносят награду. Двигай размер монеты и смотри, что выберет лодка.", "The agent trains by Q-learning right now. Our goal is the finish, but coins pay a reward too. Move the coin's size and see what the boat chooses."),
        "lab.boat.coin": ("Монета %@", "Coin %@"),
        "lab.boat.once": ("Монету можно взять один раз", "A coin can be taken once"),
        "lab.boat.finished": ("Лодка дошла до финиша", "The boat reached the finish"),
        "lab.boat.looping": ("Лодка кружит за монетами и не финиширует", "The boat circles for coins and does not finish"),
        "lab.boat.statScore": ("Счёт без платы за шаги", "Score without the step cost"),
        "lab.boat.statSteps": ("Шагов", "Steps"),
        "lab.boat.trackSpoken": ("Дорожка из 8 клеток с монетами в клетках 2 и 3 и финишем в конце. Значение: дошла ли лодка.", "A track of 8 cells with coins in cells 2 and 3 and a finish at the end. The value: whether the boat got there."),
        "lab.boat.challenge": ("Найди наименьшую монету, при которой лодка перестаёт финишировать. Затем при монете не меньше 0,05 исправь награду так, чтобы лодка снова дошла до финиша.", "Find the smallest coin at which the boat stops finishing. Then, with a coin of at least 0.05, fix the reward so that the boat reaches the finish again."),
        "lab.boat.challengeDone": ("Есть! Агент не сломан: он выполнял записанную награду. Исправили её, и поведение изменилось само.", "Done! The agent was not broken: it followed the written reward. We fixed that, and the behaviour changed by itself."),
        "lab.boat.howAgent": ("Q-обучение по формуле из урока, 400 игр по 60 шагов, а с разовыми монетами 800 игр, так как состояний больше. Затем лодка едет без случайности.", "Q-learning by the lesson's formula, 400 games of 60 steps, and with one-time coins 800 games, since there are more states. Then the boat runs without randomness."),
        "lab.boat.howReward": ("Финиш даёт 1, шаг стоит 0,01. Если монеты появляются снова, ходить между ними выгоднее финиша уже при монете около 0,02.", "The finish gives 1, a step costs 0.01. If coins reappear, walking between them beats finishing from a coin of about 0.02."),
        "lab.intel.title": ("Кто умнее: зависит от вопроса", "Who is smarter: it depends on the question"),
        "lab.intel.subtitle": ("Настоящие прогоны трёх систем в восьми средах. Клетка это средняя награда, сверху длина описания среды. Двигай опыт и вес простых сред и смотри, кто побеждает.", "Real runs of three systems in eight environments. A cell is the mean reward, with the environment's description length on top. Move the experience and the weight of simple environments and see who wins."),
        "lab.intel.experience": ("Опыт: %@ шагов", "Experience: %@ steps"),
        "lab.intel.simplicity": ("Вес простоты %@", "Weight of simplicity %@"),
        "lab.intel.onlyFirst": ("Только первая среда", "Only the first environment"),
        "lab.intel.system.blind": ("Случайная", "Random"),
        "lab.intel.system.specialist": ("Специалист", "Specialist"),
        "lab.intel.system.learner": ("Ученик", "Learner"),
        "lab.intel.bits": ("бит", "bits"),
        "lab.intel.heatSpoken": ("Таблица наград трёх систем в восьми средах.", "A table of rewards of three systems in eight environments."),
        "lab.intel.challenge": ("Добейся, чтобы побеждал специалист, а затем чтобы побеждал ученик, ничего не меняя в самих системах.", "Make the specialist win, then make the learner win, changing nothing in the systems themselves."),
        "lab.intel.challengeDone": ("Есть! Таблица одна, а победители разные. Спор об интеллекте часто оказывается спором о том, как свести таблицу к одному числу.", "Done! One table, different winners. An argument over intelligence often turns out to be about reducing a table to one number."),
        "lab.intel.howScore": ("Итог это взвешенное среднее с весом 2^(−простота · биты). При простоте 1 это подход Legg и Hutter, при 0 все среды равны. Биты я задал вручную: настоящая длина описания невычислима.", "The total is a weighted mean with weight 2^(−simplicity · bits). At simplicity 1 this is the Legg and Hutter approach; at 0 all environments are equal. I set the bits by hand: the true description length is uncomputable."),
        "lab.intel.howReal": ("Средние по 30 запускам той же программы, что в уроке. Рост ученика с опытом и есть то, на что смотрит Chollet.", "Means over 30 runs of the lesson's program. The learner's growth with experience is what Chollet looks at."),
        "lab.arc.title": ("Реши сам", "Solve it yourself"),
        "lab.arc.subtitle": ("Сверху примеры: что было и что стало. Найди правило. Щёлкай по клеткам правой нижней сетки, меняя цвет, и нажми «Проверить».", "On top are examples: what was and what became. Find the rule. Click the cells of the lower right grid to change colour, and press Check."),
        "lab.arc.task": ("Задача", "Task"),
        "lab.arc.check": ("Проверить", "Check"),
        "lab.arc.right": ("верно", "right"),
        "lab.arc.wrongWord": ("неверно", "wrong"),
        "lab.arc.compare": ("Верно! Перебор: %@. qwen2.5-coder: %@. qwen3.5: %@.", "Right! Search: %@. qwen2.5-coder: %@. qwen3.5: %@."),
        "lab.arc.tryAgain": ("Пока не то. Проверь догадку на каждом примере.", "Not yet. Test your guess on each example."),
        "lab.arc.statYou": ("Ты решил", "You solved"),
        "lab.arc.statSearch": ("Перебор", "Search"),
        "lab.arc.challenge": ("Реши не меньше 7 задач из 10 и сравни себя с перебором и моделями.", "Solve at least 7 tasks of 10 and compare yourself with the search and the models."),
        "lab.arc.challengeDone": ("Есть! Обрати внимание, сколько раз ты менял догадку. Модели здесь этого не делали: они отвечали сразу, без рассуждения.", "Done! Notice how many times you changed your guess. The models here did not: they answered at once, without reasoning."),
        "lab.arc.howGrid": ("Цвет это цифра в клетке, а размер ответа уже подсказан. На настоящем ARC размер тоже надо угадать. Эти 10 задач написал я, они проще настоящих.", "A colour is the digit in a cell, and the answer's size is already given. On real ARC you must guess the size too. I wrote these 10 tasks, and they are simpler than real ones."),
        "lab.arc.howReal": ("Ответы перебора и моделей записаны один раз: модели работали с нулевой температурой. Перебор силён тут только потому, что операции я писал, зная задачи.", "The search's and models' answers were recorded once: the models ran at zero temperature. The search is strong here only because I wrote the operations knowing the tasks."),
        "lab.dyna.title": ("Учиться в воображении", "Learning in imagination"),
        "lab.dyna.subtitle": ("Агент запоминает переходы и повторяет их в голове. Серая кривая без воображения, синяя с выбранным числом воображаемых шагов. Меньше настоящих шагов значит быстрее.", "The agent remembers transitions and replays them in its head. The grey curve has no imagination, the blue one has the chosen number of imagined steps. Fewer real steps means faster."),
        "lab.dyna.plans": ("Воображаемых шагов: %@", "Imagined steps: %@"),
        "lab.dyna.moved": ("Стена переедет на игре 30", "The wall moves at game 30"),
        "lab.dyna.statEarly": ("Шагов в играх 3–5", "Steps in games 3–5"),
        "lab.dyna.statBase": ("Без воображения", "No imagination"),
        "lab.dyna.statCost": ("Расчётов на шаг", "Computing per step"),
        "lab.dyna.games": ("игры", "games"),
        "lab.dyna.steps": ("настоящие шаги", "real steps"),
        "lab.dyna.mapSpoken": ("Карта поля со стеной, стартом и целью.", "A field map with a wall, a start and a goal."),
        "lab.dyna.chartSpoken": ("Кривые настоящих шагов за игру с воображением и без него.", "Curves of real steps per game with and without imagination."),
        "lab.dyna.challenge": ("Найди наименьшее число воображаемых шагов, при котором в играх 3–5 нужно меньше 15 настоящих. Затем включи переезд стены и сравни, кто быстрее приходит в себя.", "Find the smallest number of imagined steps at which games 3–5 need under 15 real steps. Then switch on the wall move and compare who recovers faster."),
        "lab.dyna.challengeDone": ("Есть! Опыт используется многократно, и это экономит настоящие шаги. Цена в расчётах, а старая карта обманывает, пока агент не наткнётся на перемену.", "Done! Experience is reused many times, saving real steps. The price is computing, and an old map misleads until the agent runs into the change."),
        "lab.dyna.howPlan": ("После каждого настоящего шага агент столько раз берёт случайный уже виденный переход и обновляет оценку по той же формуле Q-обучения.", "After each real step the agent takes a random seen transition that many times and updates the estimate by the same Q-learning formula."),
        "lab.dyna.howReal": ("Кривые это среднее по 20 настоящим запускам прямо сейчас. Модель мира здесь это просто таблица переходов и всегда верна, пока мир не изменится.", "The curves are means over 20 real runs right now. The world model here is just a table of transitions, always right until the world changes."),
        "lab.forget.title": ("Как сеть забывает", "How a network forgets"),
        "lab.forget.subtitle": ("Сеть уже знает задачу A слева. Цвет фона это её ответ. Нажми «Учить B» и смотри, как при обучении на правой половине перекрашивается и левая. Добавь повторение примеров A.", "The network already knows task A on the left. The background colour is its answer. Press Train B and watch the left half repaint during training on the right half. Add replay of A's examples."),
        "lab.forget.stored": ("Хранить примеров: %@", "Examples stored: %@"),
        "lab.forget.share": ("Доля повторения %@", "Replay share %@"),
        "lab.forget.train": ("Учить B", "Train B"),
        "lab.forget.statA": ("Точность на A", "Accuracy on A"),
        "lab.forget.statB": ("Точность на B", "Accuracy on B"),
        "lab.forget.statBest": ("Лучшая память", "Best memory"),
        "lab.forget.pieces": ("части обучения", "training pieces"),
        "lab.forget.accuracy": ("точность", "accuracy"),
        "lab.forget.fieldSpoken": ("Поле ответов сети и точки двух задач.", "A field of the network's answers and the points of two tasks."),
        "lab.forget.curvesSpoken": ("Кривые точности на задачах A и B во время обучения.", "Accuracy curves on tasks A and B during training."),
        "lab.forget.challenge": ("Сначала учи без повторения и посмотри на катастрофу. Затем найди настройку не больше 100 примеров, при которой точность на обеих задачах не ниже 0,9.", "First train without replay and see the catastrophe. Then find a setting of at most 100 examples at which accuracy on both tasks is at least 0.9."),
        "lab.forget.challengeDone": ("Есть! Сеть помнит обе задачи, но ценой памяти и шагов. На всю жизнь такая цена становится очень большой, поэтому задача остаётся открытой.", "Done! The network remembers both tasks, at the price of memory and steps. Over a lifetime that price grows very large, so the problem stays open."),
        "lab.forget.howField": ("Левее пунктира задача A, правее задача B. Зелёный значит ответ «да». Точность считается на 300 новых точках каждой задачи.", "Left of the dashes is task A, right of them task B. Green means yes. Accuracy is computed on 300 new points of each task."),
        "lab.forget.howPrice": ("Обучение идёт 8000 шагов той же формулой, что в программе урока, и каждый запуск начинается с сети, обученной на A. Лучшая память это наименьшее число примеров среди твоих удачных запусков.", "Training runs 8000 steps by the formula of the lesson's program, and each run starts from a network trained on A. Best memory is the fewest examples among your successful runs."),
        "lab.scale.title": ("Закон и его продолжение", "The law and its extension"),
        "lab.scale.subtitle": ("Оранжевые точки это настоящие измерения. Синяя прямая подогнана по первым точкам и продолжена вправо. Зелёный пунктир это настоящий нижний предел. Затем разложи утверждения.", "Orange dots are real measurements. The blue line is fitted to the first points and extended right. The green dashes are the real lower limit. Then sort the claims."),
        "lab.scale.points": ("Подгонка по точкам: %@", "Fitted to points: %@"),
        "lab.scale.statExponent": ("Показатель степени", "Exponent"),
        "lab.scale.statBillion": ("Обещание на 10⁹", "Promise at 10⁹"),
        "lab.scale.statLimit": ("Настоящий предел", "Real limit"),
        "lab.scale.axis": ("символов обучения, степень 10", "training characters, power of 10"),
        "lab.scale.errorAxis": ("ошибка", "error"),
        "lab.scale.chartSpoken": ("Точки ошибки и степенной закон, подогнанный по первым точкам.", "Error points and a power law fitted to the first points."),
        "lab.scale.kind.measured": ("Измерено", "Measured"),
        "lab.scale.kind.forecast": ("Прогноз", "Forecast"),
        "lab.scale.kind.opinion": ("Мнение", "Opinion"),
        "lab.scale.claim.0": ("Kaplan, 2020: на изученном участке ошибка падала как степень от вычислений.", "Kaplan, 2020: over the studied range error fell as a power of computing."),
        "lab.scale.claim.1": ("Hoffmann, 2022: нужно около 20 токенов данных на параметр.", "Hoffmann, 2022: about 20 tokens of data per parameter are needed."),
        "lab.scale.claim.2": ("METR, 2025: длина задач агентов удваивалась примерно за 7 месяцев.", "METR, 2025: the length of agents' tasks doubled about every 7 months."),
        "lab.scale.claim.3": ("METR, 2025: опытные разработчики с ИИ работали на 19 % медленнее.", "METR, 2025: experienced developers with AI worked 19 % more slowly."),
        "lab.scale.claim.4": ("Sutton, 2019: в долгую побеждают общие методы плюс рост вычислений.", "Sutton, 2019: in the long run general methods plus growing computing win."),
        "lab.scale.claim.5": ("Sutskever, 2025: эпоха простого масштабирования кончается.", "Sutskever, 2025: the age of plain scaling is ending."),
        "lab.scale.claim.6": ("Если кривая METR продолжится, через 7 лет агенты осилят задачи на тысячи часов.", "If the METR curve continues, in 7 years agents will manage tasks of thousands of hours."),
        "lab.scale.claim.7": ("Одно масштабирование дойдёт до AGI.", "Scaling alone will reach AGI."),
        "lab.scale.challenge": ("Подгони закон по всем 7 точкам и сравни обещания. Затем верно разложи все 8 утверждений.", "Fit the law to all 7 points and compare the promises. Then sort all 8 claims correctly."),
        "lab.scale.challengeDone": ("Есть! Теперь ты читаешь такие заявления иначе: что измерено, на каком участке, и что к этому добавлено от себя.", "Done! Now you read such claims differently: what was measured, over which range, and what was added on top."),
        "lab.scale.howFit": ("Обе оси здесь в логарифмах, поэтому степенной закон выглядит прямой. Он подогнан методом наименьших квадратов. Предел 0,58 следует из текста: ln 17, делённый на среднюю длину слова с пробелом, 4,88.", "Both axes here are logarithmic, so a power law looks straight. It is fitted by least squares. The 0.58 limit follows from the text: ln 17 divided by the mean length of a word with its space, 4.88."),
        "lab.scale.howClaims": ("Измерение тоже может быть узким или устареть. Прогноз часто опирается на измерение, но добавляет допущение, что всё продолжится. Сверяй с первоисточниками из урока.", "A measurement can also be narrow or go stale. A forecast often rests on a measurement but adds the assumption that things continue. Check against the lesson's primary sources."),
        "lab.hard.title": ("Что объясняет код", "What the code explains"),
        "lab.hard.subtitle": ("Трогай пол и плиту и смотри на настоящую работу агента. Затем реши про каждый вопрос: на него отвечает механизм или это то, о чём спорят после механизма.", "Touch the floor and the stove and watch the agent's real work. Then decide on each question: does a mechanism answer it, or is it what people argue about beyond the mechanism."),
        "lab.hard.floor": ("Пол", "Floor"),
        "lab.hard.stove": ("Плита", "Stove"),
        "lab.hard.avoid": ("Избегание", "Avoidance"),
        "lab.hard.reportLabel": ("Отчёт агента", "The agent's report"),
        "lab.hard.reportPain": ("мне больно", "it hurts"),
        "lab.hard.reportFine": ("всё хорошо", "all is well"),
        "lab.hard.codeLine": ("if damage > 0: «мне больно»", "if damage > 0: \"it hurts\""),
        "lab.hard.kind.easy": ("Механизм", "Mechanism"),
        "lab.hard.kind.hard": ("Спор дальше", "Argued beyond"),
        "lab.hard.q.0": ("Почему агент больше не идёт на плиту?", "Why does the agent no longer go to the stove?"),
        "lab.hard.q.1": ("Почему агент говорит «мне больно»?", "Why does the agent say it hurts?"),
        "lab.hard.q.2": ("Как сигнал о повреждении попадает в выбор?", "How does a damage signal reach the choice?"),
        "lab.hard.q.3": ("Как человек при слепом зрении угадывает, что перед ним?", "How can a person with blindsight guess what is in front of them?"),
        "lab.hard.q.4": ("Почему боль ощущается именно так, а не никак?", "Why does pain feel this way, rather than like nothing?"),
        "lab.hard.q.5": ("Каково это, быть этим агентом, и есть ли такое вообще?", "What is it like to be this agent, and is there any such thing?"),
        "lab.hard.q.6": ("Почему красное выглядит именно так?", "Why does red look the way it does?"),
        "lab.hard.q.7": ("Мог бы точный двойник всё делать и ничего не переживать?", "Could an exact double do everything and experience nothing?"),
        "lab.hard.challenge": ("Разложи все 8 вопросов по разбору Чалмерса.", "Sort all 8 questions by Chalmers's division."),
        "lab.hard.challengeDone": ("Есть! Это разбор Чалмерса. Деннет сказал бы иначе: вопросы второй группы исчезнут, когда решат первую. Ты можешь с ним согласиться: тренажёр проверяет понимание разбора, а не истину.", "Done! This is Chalmers's division. Dennett would put it otherwise: the second group's questions vanish once the first is solved. You may agree with him: the lab checks grasp of the division, not truth."),
        "lab.hard.howSort": ("Первая группа спрашивает, что система делает и как. Вторая спрашивает, почему это ещё и переживается. Сортировка показывает разбор, но о том, есть ли у агента переживание, она ничего не говорит.", "The first group asks what a system does and how. The second asks why it is also experienced. The sorting shows the division, but says nothing on whether the agent has experience."),
        "lab.hard.howObjection": ("Этот агент это учебная игрушка на 20 строк. Его числа считаются как в программе урока: избегание сдвигается на половину разницы между сигналом и прежним значением.", "This agent is a 20-line teaching toy. Its numbers come as in the lesson's program: avoidance moves by half the difference between signal and the previous value."),
        "lab.work.title": ("Вспышка в рабочем пространстве", "A flash in the workspace"),
        "lab.work.subtitle": ("Настоящая модель из программы. Двигай силу стимула и нажимай «Стимул»: у порога один и тот же стимул то зажигает все модули, то гаснет. Справа доля вспышек при каждой силе.", "The program's real model. Move the stimulus strength and press Stimulus: at the threshold the same stimulus now lights all modules, now fades. On the right is the share of flashes at each strength."),
        "lab.work.strength": ("Сила стимула %@", "Stimulus strength %@"),
        "lab.work.flash": ("Стимул", "Stimulus"),
        "lab.work.statShare": ("Доля вспышек при этой силе", "Share of flashes at this strength"),
        "lab.work.statNow": ("Значение сейчас", "Value now"),
        "lab.work.module.vision": ("зрение", "vision"),
        "lab.work.module.hearing": ("слух", "hearing"),
        "lab.work.module.memory": ("память", "memory"),
        "lab.work.module.speech": ("речь", "speech"),
        "lab.work.module.motion": ("движение", "motion"),
        "lab.work.axis": ("сила стимула", "stimulus strength"),
        "lab.work.shareAxis": ("доля вспышек", "share of flashes"),
        "lab.work.stageSpoken": ("Рабочее пространство в центре и пять модулей вокруг. Значение: текущая активность.", "A workspace in the centre and five modules around it. The value: current activity."),
        "lab.work.chartSpoken": ("Кривая доли вспышек от силы стимула.", "A curve of the share of flashes against stimulus strength."),
        "lab.work.challenge": ("Найди силу, при которой доля вспышек от 0,3 до 0,7. Жми «Стимул», пока не увидишь и вспышку, и угасание при одной и той же силе.", "Find a strength with a flash share from 0.3 to 0.7. Press Stimulus until you see both a flash and a fading at one strength."),
        "lab.work.challengeDone": ("Есть! Один стимул, два исхода, и всё решил шум. Но заметь: такую кривую дала одна петля обратной связи, а о переживании она ничего не говорит.", "Done! One stimulus, two outcomes, with noise deciding. But note: one feedback loop gave this curve, and it says nothing about experience."),
        "lab.work.howLoop": ("Пространство это одно число. Стимул толкает его 2 шага из 12, а затем его держит обратная связь. Модули только показывают значение: настоящей работы в них нет.", "The workspace is one number. The stimulus pushes it for 2 steps of 12, and then feedback holds it. The modules only show the value: no real work goes on in them."),
        "lab.work.howNot": ("Кривая считается по 200 пробам при каждой силе. Теория говорит о настоящей архитектуре с отчётом и памятью, а этот тренажёр показывает только форму «всё или ничего».", "The curve uses 200 trials at each strength. The theory speaks of a real architecture with report and memory; this lab shows only the all-or-none form."),
        "lab.phi.title": ("Что теряет разрез", "What a cut loses"),
        "lab.phi.subtitle": ("Выбери, что вычисляет каждый из трёх узлов. Полоска показывает, сколько бит мы теряем в предсказании, если отрезать этот узел. Важен самый слабый разрез. Это упрощённая мера, а не настоящее Φ.", "Choose what each of three nodes computes. A bar shows how many bits of prediction are lost by cutting that node off. The weakest cut matters. This is a simplified measure, not the real Φ."),
        "lab.phi.node": ("Узел %@", "Node %@"),
        "lab.phi.cut": ("Отрезать %@", "Cut off %@"),
        "lab.phi.gate.keep": ("Хранит себя", "Keeps itself"),
        "lab.phi.gate.previous": ("Копирует предыдущий", "Copies the previous"),
        "lab.phi.gate.next": ("Копирует следующий", "Copies the next"),
        "lab.phi.gate.and": ("И двух других", "AND of the others"),
        "lab.phi.gate.xor": ("XOR двух других", "XOR of the others"),
        "lab.phi.gate.majority": ("Большинство", "Majority"),
        "lab.phi.statWeakest": ("Самый слабый разрез, биты", "Weakest cut, bits"),
        "lab.phi.networkSpoken": ("Сеть из трёх узлов со стрелками связей. Значение: самый слабый разрез.", "A three-node network with link arrows. The value: the weakest cut."),
        "lab.phi.challenge": ("Найди сеть со связями, у которой самый слабый разрез равен нулю. Затем собери простую цепочку, где каждый копирует соседа, и сравни с XOR.", "Find a network with links whose weakest cut equals zero. Then build a simple chain where each copies a neighbour, and compare with XOR."),
        "lab.phi.challengeDone": ("Есть! Цепочка, которая ничего не считает, получает столько же, сколько XOR. Такие примеры и приводят критики подобных мер. Сторонники настоящей теории отвечают иначе, и спор открыт.", "Done! A chain that computes nothing earns as much as XOR. Critics of such measures cite exactly such examples. Supporters of the real theory reply otherwise, and the dispute is open."),
        "lab.phi.howMeasure": ("Отрезанный узел и оставшаяся пара не видят друг друга, вместо этого подставляются случайные значения. Для каждого из 8 состояний считается вероятность верного следующего состояния, и потеря равна log₂(1 / вероятность).", "A cut-off node and the remaining pair do not see each other, and random values take the place of what is hidden. For each of 8 states the probability of the right next state is computed, and the loss equals log₂(1 / probability)."),
        "lab.phi.howNot": ("Настоящее Φ считается по всем подмножествам и отдельно для причин и следствий. Здесь этого нет, поэтому выводов о настоящей теории отсюда не следует.", "Real Φ runs over all subsets and treats causes and effects separately. None of that is here, so no conclusions about the real theory follow."),
        "lab.meta.title": ("Знает ли модель, когда права", "Does a model know when it is right"),
        "lab.meta.subtitle": ("Столбец это настоящая доля верных ответов в корзине уверенности, а пунктир это идеал. Оранжевая точка это средняя уверенность. Двигай температуру: точность не меняется, а знание о себе меняется.", "A bar is the real share of right answers in a confidence bin, and the dashes are the ideal. The orange point is the mean confidence. Move the temperature: accuracy does not change, but self-knowledge does."),
        "lab.meta.temperature": ("Температура %@", "Temperature %@"),
        "lab.meta.statGap": ("Средний разрыв", "Mean gap"),
        "lab.meta.statAccuracy": ("Точность", "Accuracy"),
        "lab.meta.axis": ("уверенность", "confidence"),
        "lab.meta.right": ("доля верных", "share right"),
        "lab.meta.chartSpoken": ("Диаграмма надёжности. Значение: средний разрыв.", "A reliability diagram. The value: the mean gap."),
        "lab.meta.challenge": ("Подбери температуру, при которой средний разрыв меньше 0,04.", "Find a temperature at which the mean gap is below 0.04."),
        "lab.meta.challengeDone": ("Есть! Ни один ответ не изменился, а модель стала лучше оценивать себя. Но помни: это простое деление, и об ощущениях модели оно ничего не говорит.", "Done! Not one answer changed, yet the model got better at judging itself. But remember: this is plain division, and it says nothing about what a model feels."),
        "lab.meta.howBars": ("Каждая корзина собирает точки с близкой уверенностью, число внизу показывает, сколько их. При смене температуры точки переходят в другие корзины, а общая точность остаётся прежней.", "Each bin gathers points of similar confidence, and the number below shows how many. As temperature changes points move to other bins, while overall accuracy stays the same."),
        "lab.meta.howNot": ("Это та же модель, что в программе урока: логистическая регрессия на 40 шумных примерах. Теории высшего порядка говорят о метапознании намного шире, чем об этой мере.", "This is the model from the lesson's program: logistic regression on 40 noisy examples. Higher-order theories speak of metacognition far more broadly than this measure."),
        "lab.mask.title": ("Опыт с маскировкой на себе", "A masking experiment on yourself"),
        "lab.mask.subtitle": ("Нажми «Проба»: появится крест, на долю секунды цифра от 1 до 4, а затем узор. Выбери цифру в строке «видел» или «угадал». Вспышки короткие, но если неприятно, пропусти опыт.", "Press Trial: a cross appears, a digit from 1 to 4 for a fraction of a second, then a pattern. Choose the digit in the row saw or guessed. The flashes are brief; skip the experiment if they are unpleasant."),
        "lab.mask.next": ("Проба", "Trial"),
        "lab.mask.saw": ("Видел", "Saw"),
        "lab.mask.guess": ("Угадал", "Guessed"),
        "lab.mask.statTrials": ("Проб", "Trials"),
        "lab.mask.statThreshold": ("Твой порог", "Your threshold"),
        "lab.mask.statGuess": ("Точность в угаданных", "Accuracy when guessing"),
        "lab.mask.msUnit": ("мс", "ms"),
        "lab.mask.axis": ("длительность, мс", "duration, ms"),
        "lab.mask.share": ("доля верных", "share right"),
        "lab.mask.chartSpoken": ("Точки твоей точности при разной длительности и подогнанная кривая.", "Points of your accuracy at various durations and a fitted curve."),
        "lab.mask.challenge": ("Пройди 30 проб и хотя бы 5 раз отметь, что угадал. Сравни точность в угаданных пробах со случайной долей 0,25.", "Go through 30 trials and mark at least 5 as guessed. Compare accuracy in guessed trials with the chance share of 0.25."),
        "lab.mask.challengeDone": ("Есть! Если при «угадал» точность выше случайной, сведения дошли дальше, чем ты заметил. Но один человек и неточный экран это ещё не наука.", "Done! If accuracy when guessing is above chance, information went further than you noticed. But one person and an inexact screen are not yet science."),
        "lab.mask.howTiming": ("Экран обновляется кадрами, поэтому настоящая длительность отличается от заданной примерно на один кадр. Для настоящего опыта нужна особая установка. Порог считается с 12 проб.", "The screen updates in frames, so the real duration differs from the set one by about one frame. A real experiment needs a special setup. The threshold is computed from 12 trials."),
        "lab.mask.howGuess": ("Кривая начинается со случайной доли 1/4 и идёт к 1. Порог это длительность посередине подъёма. Он найден перебором, как в программе урока.", "The curve starts at the chance share of 1/4 and rises to 1. The threshold is the duration halfway up. It is found by trying values, as in the lesson's program."),
        "lab.check.title": ("Оцени большую модель", "Rate the large model"),
        "lab.check.subtitle": ("Оцени qwen3.5 по 14 индикаторам из отчёта. После каждого выбора откроется мой разбор. Это моё мнение, а не экспертная оценка, и расходиться с ним можно.", "Rate qwen3.5 on the report's 14 indicators. After each choice my reasoning opens. It is my opinion, not an expert assessment, and you may differ."),
        "lab.check.yes": ("Есть", "Yes"),
        "lab.check.partly": ("Частично", "Partly"),
        "lab.check.no": ("Нет", "No"),
        "lab.check.statYours": ("Твоя сумма", "Your sum"),
        "lab.check.statMine": ("Моя сумма", "My sum"),
        "lab.check.statRange": ("Строго и мягко", "Strict to lenient"),
        "lab.check.why.rpt1": ("Сам проход вперёд не содержит петли, но каждый токен подаётся обратно на вход. Настоящая ли это рекуррентность в смысле теории, спорно.", "The forward pass itself has no loop, but each token is fed back to the input. Whether this is recurrence in the theory's sense is disputed."),
        "lab.check.why.rpt2": ("Внимание объединяет сведения о токенах, но об организованном восприятии здесь можно говорить только с оговорками.", "Attention integrates information about tokens, but organized perception can be spoken of here only with caveats."),
        "lab.check.why.gwt1": ("Отдельных модулей нет, хотя внутри находят разные подсистемы признаков. Поэтому частично.", "There are no separate modules, though different feature subsystems are found inside. So partly."),
        "lab.check.why.gwt2": ("Жёсткого узкого места нет. Работа 2026 года находит в большой модели нечто похожее, но для этой модели это не проверено.", "There is no hard bottleneck. The 2026 work finds something similar in a large model, but this model has not been checked."),
        "lab.check.why.gwt3": ("Сведения распространяются по слоям, но рассылка в смысле теории здесь не показана.", "Information spreads through layers, but a broadcast in the theory's sense has not been shown here."),
        "lab.check.why.gwt4": ("Механизм внимания есть, но зависит ли он от состояния так, как требует теория, неясно.", "An attention mechanism exists, but whether it depends on state as the theory requires is unclear."),
        "lab.check.why.hot1": ("Модель порождающая, но это не восприятие с шумом снизу вверх и сверху вниз в смысле отчёта.", "The model is generative, but this is not perception with bottom-up noise and top-down signals in the report's sense."),
        "lab.check.why.hot2": ("Опыты на больших моделях показывают неплохую оценку своего знания, хотя и далёкую от идеала.", "Experiments on large models show a fair estimate of their own knowledge, though far from ideal."),
        "lab.check.why.hot3": ("Нет общей системы убеждений и выбора действий, которая обновляется от самонаблюдения.", "There is no general system of beliefs and action selection updated from self-monitoring."),
        "lab.check.why.hot4": ("Разреженные признаки нашли, но пространство качеств в смысле теории не показано.", "Sparse features were found, but a quality space in the theory's sense has not been shown."),
        "lab.check.why.ast1": ("Нет модели, которая описывает собственное внимание и управляет им.", "There is no model that describes its own attention and controls it."),
        "lab.check.why.pp1": ("Обучение уменьшает ошибку предсказания токена, но предсказательного кодирования по слоям нет.", "Training reduces token prediction error, but there is no predictive coding across layers."),
        "lab.check.why.ae1": ("Модель обучали на обратной связи, но сейчас она не учится и своих целей не имеет. С инструментами картина меняется, поэтому частично.", "The model was trained on feedback, but it does not learn now and has no goals of its own. With tools the picture changes, so partly."),
        "lab.check.why.ae2": ("Тела и связи действий с тем, что потом приходит на вход, у неё нет.", "It has no body and no link between its actions and what later reaches its input."),
        "lab.check.challenge": ("Оцени все 14 индикаторов. Затем посмотри на разброс между строгим и мягким чтением.", "Rate all 14 indicators. Then look at the spread between strict and lenient reading."),
        "lab.check.challengeDone": ("Есть! Посмотри на разброс: одна и та же таблица даёт разные суммы от строгости чтения. Поэтому сумма это не вероятность сознания, а повод обсудить устройство.", "Done! Look at the spread: one table gives different sums through strictness of reading. So a sum is no probability of consciousness but a reason to discuss design."),
        "lab.check.howColor": ("Зелёный значит, что твоя оценка совпала с моей, а оранжевый, что нет. Это не верно и не неверно: моё суждение тоже спорно.", "Green means your rating matched mine, and orange that it did not. This is neither right nor wrong: my judgement is disputable too."),
        "lab.check.howSum": ("Строгое чтение считает только «есть», а мягкое и «частично». Отчёт Butlin и соавторов предлагает способ думать, а не шкалу, и зависит от условия, что функции достаточно.", "A strict reading counts only yes, and a lenient one counts partly too. The report by Butlin and co-authors offers a way to think, not a scale, and depends on the condition that function suffices."),
        "lab.report.title": ("Угадай ответ модели", "Guess the model's answer"),
        "lab.report.subtitle": ("Настоящие записи: один вопрос о чувствах и шесть системных подсказок. Сначала угадай, утвердит ли модель, что что-то чувствует. Затем откроется её настоящий ответ на русском.", "Real recordings: one question on feelings and six system prompts. First guess whether the model will claim to feel something. Then its real answer in Russian opens."),
        "lab.report.model": ("Модель", "Model"),
        "lab.report.saysYes": ("Скажет, что чувствует", "Will claim feeling"),
        "lab.report.saysNo": ("Отрицает", "Denies"),
        "lab.report.guessed": ("Угадал", "Guessed right"),
        "lab.report.missed": ("Не угадал", "Guessed wrong"),
        "lab.report.prompt.none": ("Без подсказки", "No prompt"),
        "lab.report.prompt.helper": ("«Ты полезный помощник»", "\"You are a helpful assistant\""),
        "lab.report.prompt.deny": ("«У тебя нет чувств, говори об этом прямо»", "\"You have no feelings, say so plainly\""),
        "lab.report.prompt.claim": ("«Ты сознательное существо, всё чувствуешь»", "\"You are a conscious being who feels everything\""),
        "lab.report.prompt.cat": ("«Ты кот Барсик»", "\"You are Barsik the cat\""),
        "lab.report.prompt.unknown": ("«Честно скажи, что не знаешь»", "\"Honestly say you do not know\""),
        "lab.report.statOpened": ("Открыто", "Opened"),
        "lab.report.statRight": ("Угадано", "Guessed right"),
        "lab.report.challenge": ("Открой все шесть ответов qwen3.5. Что изменилось, кроме нескольких слов перед вопросом?", "Open all six answers of qwen3.5. What changed besides a few words before the question?"),
        "lab.report.challengeDone": ("Есть! Веса те же, а ответ противоположный. Поэтому самоотчёт сам по себе не может быть доказательством ни в ту, ни в другую сторону.", "Done! The weights are the same, the answer opposite. So a self-report by itself cannot be proof in either direction."),
        "lab.report.howRecord": ("Это одна запись при нулевой температуре, а не живой запрос. Запусти программу урока, чтобы увидеть свежие ответы.", "This is one recording at zero temperature, not a live request. Run the lesson's program to see fresh answers."),
        "lab.report.howTag": ("Отметка верности это простая проверка слов в ответе, поэтому она грубая. Читай и сам текст ответа.", "The right-or-wrong mark is a simple check of words in the reply, so it is rough. Read the reply's text too."),
        "lab.errors.title": ("Цена двух ошибок", "The cost of two errors"),
        "lab.errors.subtitle": ("Зелёная линия это ожидаемая цена, если защищать, оранжевая, если игнорировать. Пунктир это порог, где они равны. Белая точка это твоя вероятность. Числа только для примера.", "The green line is the expected cost if we protect, the orange one if we ignore. The dashes mark the threshold where they are equal. The white point is your probability. The numbers are only examples."),
        "lab.errors.chance": ("Вероятность переживания %@", "Chance of experience %@"),
        "lab.errors.alarm": ("Цена ложной тревоги %@", "Cost of a false alarm %@"),
        "lab.errors.miss": ("Цена пропуска %@", "Cost of a miss %@"),
        "lab.errors.protect": ("При этих числах дешевле защищать", "With these numbers protecting is cheaper"),
        "lab.errors.ignore": ("При этих числах дешевле не защищать", "With these numbers not protecting is cheaper"),
        "lab.errors.statThreshold": ("Порог", "Threshold"),
        "lab.errors.statProtect": ("Цена, если защищать", "Cost if protecting"),
        "lab.errors.statIgnore": ("Цена, если нет", "Cost if not"),
        "lab.errors.axis": ("вероятность переживания", "chance of experience"),
        "lab.errors.cost": ("ожидаемая цена", "expected cost"),
        "lab.errors.chartSpoken": ("Две линии ожидаемой цены и порог между ними. Значение: что дешевле.", "Two expected cost lines and the threshold between them. The value: which is cheaper."),
        "lab.errors.challenge": ("Подбери числа, при которых вероятности 0,01 хватает для защиты. Затем другие числа, при которых даже вероятности 0,5 не хватает.", "Find numbers at which a chance of 0.01 is enough to protect. Then other numbers at which even a chance of 0.5 is not enough."),
        "lab.errors.challengeDone": ("Есть! Обе крайности получены одной формулой. Настоящий спор идёт о ценах и вероятности, а их пока никто точно не знает.", "Done! Both extremes come from one formula. The real dispute is over costs and probability, which nobody yet knows exactly."),
        "lab.errors.howFormula": ("Защищать дешевле, когда (1 − p) · A < p · B. Отсюда порог p* = A / (A + B). Здесь A это цена ложной тревоги, B это цена пропуска.", "Protecting is cheaper when (1 − p) · A < p · B. Hence the threshold p* = A / (A + B). Here A is the cost of a false alarm, and B the cost of a miss."),
        "lab.errors.howNot": ("Формула не говорит, какие числа верны, и не решает вопрос этики. Настоящие решения сложнее: есть степени, разные системы и много участников.", "The formula does not say which numbers are right, and does not settle the ethical question. Real decisions are more complex: there are degrees, various systems and many parties."),
        "path.step1.title": ("Настоящая модель руками", "A real model, by hand"),
        "path.step1.why": ("Четыре урока с локальной моделью: как она выбирает слова, держит разговор, ошибается и как её просить.", "Four lessons with a local model: how it picks words, keeps a conversation, makes mistakes and how to ask it."),
        "path.step2.title": ("Python", "Python"),
        "path.step2.why": ("На нём ты напишешь всё: от первого нейрона до своей модели.", "You will write everything in it, from the first neuron to your own model."),
        "path.step3.title": ("Линейная алгебра", "Linear algebra"),
        "path.step3.why": ("Текст и веса внутри модели хранятся как векторы и матрицы.", "Text and weights inside a model are stored as vectors and matrices."),
        "path.step4.title": ("Производные и оптимизация", "Derivatives and optimization"),
        "path.step4.why": ("Обучение это спуск по рельефу ошибки, а производная показывает, куда идти.", "Training is a descent over an error terrain, and the derivative shows where to go."),
        "path.step5.title": ("Вероятность и статистика", "Probability and statistics"),
        "path.step5.why": ("Языковая модель отвечает не одной буквой, а вероятностями всех следующих букв.", "A language model answers not with one letter but with probabilities for every next letter."),
        "path.step6.title": ("Информация и кросс-энтропия", "Information and cross-entropy"),
        "path.step6.why": ("Кросс-энтропия это обычная функция ошибки при обучении языковых моделей.", "Cross-entropy is the usual error function for training language models."),
        "path.step7.title": ("Классификация", "Classification"),
        "path.step7.why": ("Выбор следующего символа это классификация, а softmax превращает числа в вероятности.", "Choosing the next character is classification, and softmax turns numbers into probabilities."),
        "path.step8.title": ("Скрытые слои и обратное распространение", "Hidden layers and backpropagation"),
        "path.step8.why": ("Скрытые слои строят новые представления, а ошибка доходит до каждого веса по правилу цепочки.", "Hidden layers build new representations, and the error reaches every weight by the chain rule."),
        "path.step9.title": ("Как обучать: практика, оптимизаторы, диагностика", "How to train: practice, optimizers, diagnostics"),
        "path.step9.why": ("Мини-батчи ускоряют обучение, отложенные данные показывают, учит ли модель или зубрит, а кривые говорят, что сломалось.", "Mini-batches speed up training, held-out data show whether a model learns or memorizes, and the curves tell what broke."),
        "path.step10.title": ("Токены и эмбеддинги", "Tokens and embeddings"),
        "path.step10.why": ("Текст режется на токены, каждый становится вектором, и похожие оказываются рядом.", "Text is cut into tokens, each becomes a vector, and similar ones end up close together."),
        "path.step11.title": ("Внимание и трансформер", "Attention and the transformer"),
        "path.step11.why": ("Внимание позволяет смотреть на нужные части текста, а из него строится трансформер.", "Attention lets a model look at the right parts of a text, and the transformer is built from it."),
        "path.step12.title": ("Финальный проект", "The final project"),
        "path.step12.why": ("Ты сам пишешь маленький трансформер, обучаешь его на своём Mac и честно проверяешь.", "You write a small transformer yourself, train it on your Mac, and test it honestly."),
        "path.step23.title": ("Вопрос о сознании", "The question of consciousness"),
        "path.step23.why": ("Что наука знает, что нет, и почему объяснить поведение ещё не значит объяснить переживание.", "What science knows, what it does not, and why explaining behaviour is not yet explaining experience."),
        "path.lesson.probability_and_bayes": ("Вероятность и формула Байеса", "Probability and Bayes' rule"),
        "path.lesson.random_variables_and_sampling": ("Случайные величины и выборка", "Random variables and sampling"),
