        "lab.trigonometry.coordinates": ("Точка (cos θ; sin θ) = (%@; %@)", "Point (cos θ, sin θ) = (%@, %@)"),
        "lab.trigonometry.question": ("Проверь прогноз", "Check your prediction"),
        "lab.trigonometry.questionAngle": ("При %@ какой знак у sin θ?", "At %@, what is the sign of sin θ?"),
        "lab.trigonometry.option.negative": ("Отрицательный", "Negative"),
        "lab.trigonometry.option.zero": ("Нулевой", "Zero"),
        "lab.trigonometry.option.positive": ("Положительный", "Positive"),
        "lab.trigonometry.correct": ("Верно.", "Correct."),
        "lab.trigonometry.retryHint": ("Пока нет. Проверь, выше, на или ниже горизонтальной оси находится точка.", "Not yet. Check whether the point is above, on, or below the horizontal axis."),
        "lab.trigonometry.showExplanation": ("Показать разбор", "Show explanation"),
        "lab.trigonometry.explanation.negative": ("При %@ точка ниже горизонтальной оси: y = sin θ = %@ < 0. Поэтому синус отрицательный.", "At %@, the point is below the horizontal axis: y = sin θ = %@ < 0. Therefore, the sine is negative."),
        "lab.trigonometry.explanation.zero": ("При %@ точка лежит на горизонтальной оси: y = sin θ = %@. Поэтому синус равен нулю.", "At %@, the point lies on the horizontal axis: y = sin θ = %@. Therefore, the sine is zero."),
        "lab.trigonometry.explanation.positive": ("При %@ точка выше горизонтальной оси: y = sin θ = %@ > 0. Поэтому синус положительный.", "At %@, the point is above the horizontal axis: y = sin θ = %@ > 0. Therefore, the sine is positive."),
        "lab.trigonometry.tryAgain": ("Перемешать варианты и попробовать снова", "Shuffle the choices and try again"),
        "lab.trigonometry.limits": ("График показывает угол от −2π до 2π и значения от −1 до 1; это учебная визуализация, а не измерение физического процесса. Ползунок меняет угол шагами по 5°; вычисления используют математические функции синуса и косинуса.", "The graph shows angles from −2π to 2π and values from −1 to 1; it is a learning visualization, not a measurement of a physical process. The slider moves in 5° steps; calculations use the mathematical sine and cosine functions."),
        "lab.optimization.hint": ("Двигай выбранную точку ползунком или перетаскивай её по окружности. Предскажи, где производная вдоль ограничения станет нулевой.", "Move the selected point with the slider or drag it around the circle. Predict where the derivative along the constraint becomes zero."),
        "lab.optimization.graph": ("Единичная окружность ограничения x² + y² = 1. Пунктирные диагонали отмечают направления стационарных точек; цветная точка выбирает текущую позицию.", "Unit-circle constraint x² + y² = 1. Dashed diagonals mark stationary directions; the colored point selects the current position."),
        "lab.optimization.angle": ("Положение на окружности", "Position on the circle"),
        "lab.optimization.constraint": ("Ограничение", "Constraint"),
        "lab.optimization.candidates": ("Стационарные направления", "Stationary directions"),
        "lab.optimization.selected": ("Текущая точка", "Selected point"),
        "lab.optimization.point": ("Точка: (%@; %@)", "Point: (%@, %@)"),
        "lab.optimization.objective": ("Цель xy: %@", "Objective xy: %@"),
        "lab.optimization.derivative": ("Изменение xy вдоль окружности: %@", "Rate of change of xy along the circle: %@"),
        "lab.optimization.nonStationary": ("Точка допустима, но не стационарна: движение по окружности меняет значение xy.", "The point is feasible but not stationary: moving along the circle changes xy."),
        "lab.optimization.maximum": ("Стационарный максимум: значение xy равно 1/2.", "Stationary maximum: xy equals 1/2."),
        "lab.optimization.minimum": ("Стационарный минимум: значение xy равно −1/2.", "Stationary minimum: xy equals −1/2."),
        "lab.optimization.multiplier": ("Множитель λ в этой точке: %@", "Lagrange multiplier λ at this point: %@"),
        "lab.optimization.viewMode": ("Вид", "View"),
        "lab.optimization.view2D": ("Плоскость: окружность", "Plane: circle"),
        "lab.optimization.view3D": ("3D: поверхность z = xy", "3D: surface z = xy"),
        "lab.optimization.surfaceLabel": ("Трёхмерная поверхность z = xy в форме седла. Цилиндр x² + y² = 1 вырезает на ней замкнутую кривую допустимых точек; на кривой отмечены два максимума и два минимума.", "Three-dimensional saddle surface z = xy. The cylinder x² + y² = 1 cuts a closed curve of feasible points on it; the curve marks two maxima and two minima."),
        "lab.optimization.surfaceValue": ("Точка (%@; %@), высота xy = %@, угол между ∇f и ∇g: %@", "Point (%@, %@), height xy = %@, angle between ∇f and ∇g: %@"),
        "lab.optimization.surfaceHint": ("Вращай сцену мышью или трекпадом, приближай колёсиком или жестом. Двигай точку ползунком: на кривой пересечения высота xy — это значение цели. В максимуме и минимуме стрелки ∇f и ∇g ложатся на одну прямую — это и есть условие ∇f = λ∇g.", "Rotate the scene with the mouse or trackpad and zoom with the wheel or a pinch. Move the point with the slider: on the intersection curve the height xy is the objective value. At a maximum or minimum the arrows ∇f and ∇g line up — that is the condition ∇f = λ∇g."),
        "lab.optimization.legendGradF": ("∇f — рост xy", "∇f — growth of xy"),
        "lab.optimization.legendGradG": ("∇g — нормаль к окружности", "∇g — normal to the circle"),
        "lab.optimization.legendExtrema": ("максимумы зелёные, минимумы красные", "maxima green, minima red"),
        "lab.optimization.gradientAngle": ("Угол между ∇f и ∇g: %@° (условие Лагранжа: 0° или 180°)", "Angle between ∇f and ∇g: %@° (Lagrange condition: 0° or 180°)"),
        "lab.optimization.limits": ("Это двумерная учебная модель для гладкого равенства. Цветные точки показывают кандидатов; метод Лагранжа сам по себе не классифицирует кандидата без сравнения значений.", "This is a two-dimensional teaching model for a smooth equality. Colored points mark candidates; Lagrange's method does not classify them without comparing values."),
        "lab.slope": ("Наклон", "Slope"),
        "lab.force": ("Сила", "Force"),
        "lab.forcePredictionPrompt": ("Прогноз: если равнодействующая сила удвоится, а масса останется прежней, что произойдёт с ускорением?", "Predict: if the net force doubles while mass stays the same, what happens to acceleration?"),
        "lab.forcePredictionOption.0": ("Уменьшится вдвое", "It halves"),
        "lab.forcePredictionOption.1": ("Не изменится", "It stays the same"),
        "lab.forcePredictionOption.2": ("Увеличится вдвое", "It doubles"),
        "lab.forcePredictionWrong": ("Пока не сходится. Подумай, как сила связана с ускорением при постоянной массе.", "Not quite. Think about how force relates to acceleration when mass is constant."),
        "lab.forcePredictionHint": ("Подсказка: a = F / m. Масса не меняется — проследи, что происходит при удвоении F.", "Hint: a = F / m. Mass stays constant—track what happens when F doubles."),
        "lab.forcePredictionCorrect": ("Верно: при постоянной массе удвоение силы удваивает ускорение. Измени параметры ниже и проверь это в опыте.", "Correct: with constant mass, doubling force doubles acceleration. Change the controls below and check it in the experiment."),
        "lab.forcePredictionRetry": ("Попробовать ещё раз", "Try again"),
        "lab.forcePredictionNew": ("Новый прогноз", "New prediction"),
        "lab.mass": ("Масса", "Mass"),
        "lab.acceleration": ("Ускорение", "Acceleration"),
        "lab.force3DHint": ("Перетаскивай сцену для вращения. Метки дорожки — метры; размер блока условно показывает массу, стрелка — силу. Отрицательная сила направлена влево.", "Drag to orbit the scene. Track labels are in metres; box size illustrates mass, and the arrow shows force. Negative force points left."),
        "lab.forceAssumptions": ("Старт из покоя: x = 0, v = 0. Постоянная суммарная сила, движение вдоль одной оси, без трения. Опыт длится 2 секунды. Изменение силы или массы сбрасывает опыт.", "Starts at rest: x = 0, v = 0. Constant net force, motion along one axis, no friction. The experiment lasts 2 seconds. Changing force or mass resets it."),
        "lab.motionPlay": ("Запуск", "Play"),
        "lab.motionPause": ("Пауза", "Pause"),
        "lab.motionStep": ("Шаг +0,1 с", "Step +0.1 s"),
        "lab.motionReset": ("Сброс", "Reset"),
        "lab.motionTime": ("Время", "Time"),
        "lab.motionVelocity": ("Скорость вдоль оси", "Signed velocity"),
        "lab.motionDisplacement": ("Перемещение", "Displacement"),
        "lab.motionReduced": ("Включено уменьшение движения. Исследуй опыт кнопкой «Шаг»: все значения доступны без непрерывной анимации.", "Reduce Motion is enabled. Explore with Step: all readings are available without continuous animation."),
        "lab.motionFinished": ("Опыт завершён на отметке 2 с. Запуск повторит его из покоя.", "The experiment ended at 2 s. Play starts it again from rest."),
        "lab.forceExperiment": ("Предскажи: как изменится перемещение за 2 с, если удвоить массу при той же силе? Проверь двумя опытами. Затем задай F = 0 и объясни, почему блок остаётся на месте при наших начальных условиях.", "Predict: how does displacement after 2 s change if mass doubles at the same force? Compare two runs. Then set F = 0 and explain why the block stays still with these initial conditions."),
        "lab.measurementTitle": ("Шкала измерения", "Measurement scale"),
        "lab.measurementHint": ("Предскажи результат в метрах. Затем меняй длину и неопределённость: точка показывает оценку, а цветная полоса — заданный диапазон ±.", "Predict the result in metres. Then change the length and uncertainty: the dot marks the estimate and the coloured band shows the stated ± range."),
        "lab.measurementBand": ("Диапазон заданной неопределённости", "Stated uncertainty range"),
        "lab.measurementLength": ("Измеренная длина, см", "Measured length, cm"),
        "lab.measurementUncertainty": ("Абсолютная неопределённость, см", "Absolute uncertainty, cm"),
        "lab.measurementRelative": ("Относительная неопределённость", "Relative uncertainty"),
        "lab.measurementLimits": ("Полоса — арифметический диапазон, не гарантия истинного значения или доверительный интервал. Способ оценки неопределённости здесь не моделируется.", "The band is an arithmetic range, not a guarantee about the true value or a confidence interval. This lab does not model how uncertainty was estimated."),
        "lab.frictionHint": ("Увеличивай толчок и наблюдай порог начала скольжения. До порога трение покоя подстраивается под толчок; после него модель переключается на трение скольжения.", "Increase the push and observe the threshold for sliding. Below it, static friction adjusts to the push; above it, the model switches to kinetic friction."),
        "lab.frictionBlock": ("Брусок на горизонтальной поверхности", "Block on a level surface"),
        "lab.frictionPush": ("Толчок", "Applied push"),
        "lab.frictionStaticCoefficient": ("Коэффициент трения покоя μₛ", "Static-friction coefficient μₛ"),
        "lab.frictionKineticCoefficient": ("Коэффициент трения скольжения μₖ", "Kinetic-friction coefficient μₖ"),
        "lab.frictionThreshold": ("Порог начала движения", "Threshold for motion"),
        "lab.frictionResting": ("Покой: трение уравновешивает толчок", "At rest: friction balances the push"),
        "lab.frictionSliding": ("Скольжение: трение направлено против движения", "Sliding: friction opposes the motion"),
        "lab.frictionNormal": ("Нормальная сила", "Normal force"),
        "lab.frictionForce": ("Сила трения", "Friction force"),
        "lab.frictionAcceleration": ("Ускорение", "Acceleration"),
        "lab.frictionVelocity": ("Скорость через выбранное время", "Speed at selected time"),
        "lab.frictionDisplacement": ("Путь от начала опыта", "Distance from the start"),
        "lab.frictionTime": ("Время опыта", "Experiment time"),
        "lab.frictionPredictionTitle": ("Предскажи движение", "Predict the motion"),
        "lab.frictionPredictionQuestion": ("В примере с массой 5 кг и μₛ = 0,4: что произойдёт при горизонтальном толчке %.0f Н?", "In the 5 kg example with μₛ = 0.4, what happens under a horizontal push of %.0f N?"),
        "lab.frictionPredictionRest": ("Останется в покое", "Stays at rest"),
        "lab.frictionPredictionSlide": ("Начнёт скользить", "Starts sliding"),
        "lab.frictionPrediction.rest.correct": ("Верно: 15 Н меньше порога 19,62 Н. Трение покоя уравновешивает толчок — блок остаётся в покое.", "Correct: 15 N is below the 19.62 N threshold. Static friction balances the push, so the block stays at rest."),
        "lab.frictionPrediction.rest.review": ("Проверь порог: 15 Н < 19,62 Н. Трение покоя уравновешивает толчок, поэтому блок не скользит.", "Check the threshold: 15 N < 19.62 N. Static friction balances the push, so the block does not slide."),
        "lab.frictionPrediction.slide.correct": ("Верно: 25 Н больше 19,62 Н, поэтому начинается скольжение. После старта модель использует трение скольжения около 14,7 Н.", "Correct: 25 N exceeds 19.62 N, so sliding begins. After motion starts, the model uses about 14.7 N of kinetic friction."),
        "lab.frictionPrediction.slide.review": ("Сравни толчок с порогом 19,62 Н: 25 Н больше, поэтому начинается скольжение; затем действует трение около 14,7 Н.", "Compare the push with the 19.62 N threshold: 25 N is greater, so sliding begins; kinetic friction then acts at about 14.7 N."),
        "lab.frictionPredictionCheck": ("Проверить ответ", "Check answer"),
        "lab.frictionPredictionNext": ("Следующий пример", "Next example"),
        "lab.frictionPredictionFinish": ("Завершить", "Finish"),
        "lab.frictionPredictionComplete": ("Оба случая разобраны. Попробуй ещё раз или продолжай исследовать параметры.", "Both cases are complete. Try them again or keep exploring the controls."),
        "lab.frictionPredictionRestart": ("Пройти ещё раз", "Try again"),
        "lab.frictionLimits": ("Учебная модель: ровная поверхность, постоянные коэффициенты и старт из покоя; принято μₖ ≤ μₛ — это не универсально для всех поверхностей. Не учитываются нагрев, деформация, сопротивление воздуха и качение.", "Introductory model: level surface, constant coefficients, and a start from rest; μₖ ≤ μₛ is assumed, but this is not universal for all surfaces. Heating, deformation, air resistance, and rolling are omitted."),
        "lab.frictionPrediction": ("Проверь пример: при 5 кг и μₛ = 0,4 порог около 19,6 Н. Предскажи, покоится ли блок при 15 Н и 25 Н.", "Check the example: at 5 kg and μₛ = 0.4, the threshold is about 19.6 N. Predict whether the block rests at 15 N and 25 N."),
        "lab.projectile.title": ("Полёт без сопротивления воздуха", "Flight without air resistance"),
        "lab.projectile.hint": ("Горизонтальное движение равномерное, вертикальное ускоряется под действием тяжести. Меняй угол и скорость, затем двигай ползунок времени.", "Horizontal motion is uniform while gravity accelerates the vertical motion. Change the angle and speed, then move the time slider."),
        "lab.projectile.chart": ("Траектория полёта; точка показывает текущее положение", "Projectile trajectory; the dot marks the current position"),
        "lab.projectile.current": ("Выбранный угол", "Selected angle"),
        "lab.projectile.compare": ("Сравнить с дополняющим углом", "Compare complementary angle"),
        "lab.projectile.hideCompare": ("Скрыть сравнение", "Hide comparison"),
        "lab.projectile.speed": ("Начальная скорость", "Launch speed"),
        "lab.projectile.angle": ("Угол к горизонту", "Angle above horizontal"),
        "lab.projectile.time": ("Время полёта", "Flight time"),
        "lab.projectile.range": ("Дальность", "Range"),
        "lab.projectile.height": ("Максимальная высота", "Maximum height"),
        "lab.projectile.flight": ("Полное время полёта", "Total flight time"),
        "lab.projectile.position": ("Горизонтальная координата", "Horizontal position"),
        "lab.projectile.compareTask": ("Сравни углы θ и 90° − θ при одной скорости: на одинаковой высоте старта и посадки идеальная модель даёт одинаковую дальность, но разные вершины траектории. Объясни, где проходит более высокая дуга.", "Compare θ and 90° − θ at the same speed: with equal launch and landing heights, the ideal model gives the same range but different peak heights. Explain which arc rises higher."),
        "lab.projectile.limits": ("Модель предполагает постоянное g = 9,81 м/с², старт и посадку на одном уровне, точечное тело и отсутствие сопротивления воздуха, ветра и вращения. Реальный полёт может заметно отличаться.", "The model assumes constant g = 9.81 m/s², equal launch and landing heights, a point object, and no air resistance, wind, or spin. Real flight can differ substantially."),
        "lab.energyHint": ("Меняй параметры и наблюдай, как работа меняет кинетическую энергию. Скорость влияет на неё сильнее массы: она входит в квадрате.", "Change the controls and see how work changes kinetic energy. Speed has a stronger effect than mass because it is squared."),
        "lab.energyInitial": ("До работы", "Before work"),
        "lab.energyFinal": ("После работы", "After work"),
        "lab.energyFinalSpeed": ("Конечная скорость", "Final speed"),
        "lab.energyInitialSpeed": ("Начальная скорость", "Initial speed"),
        "lab.energyNetWork": ("Работа сил", "Net work"),
        "lab.energy3DHint": ("Перетаскивай 3D-сцену, чтобы вращать её. Масса меняет размер тележки, а скорость — темп её движения по дорожке.", "Drag to orbit the 3D scene. Mass changes the cart's size; speed changes how quickly it moves along the track."),
        "lab.energyStops": ("Такая суммарная работа дала бы отрицательную кинетическую энергию. Если её вызвала тормозящая сила, тележка остановится раньше. Уменьши модуль работы или увеличь начальную скорость.", "This net work would imply negative kinetic energy. If a braking force causes it, the cart stops first. Reduce the work magnitude or increase its initial speed."),
        "lab.energyBars": ("Столбики: энергия до, работа сил и энергия после — теорема о работе и энергии.", "Bars: energy before, the net work, and energy after: the work–energy theorem."),
        "lab.energyChallenge": ("Подбери работу сил так, чтобы тело ровно остановилось: конечная скорость 0.", "Choose the net work so that the body stops exactly: final speed 0."),
        "lab.energyChallengeSolved": ("Да: отрицательная работа ровно равна начальной энергии, W = −½mv². Так тормоза превращают энергию движения в тепло.", "Yes: the negative work exactly equals the starting energy, W = −½mv². This is how brakes turn the energy of motion into heat."),
        "lab.buildSentence": ("Собери предложение, нажимая на слова:", "Build the sentence by tapping the words:"),
        "lab.tensePrompt": ("Выбери вариант, который подходит к ситуации:", "Choose the form that fits the situation:"),
        "lab.tenseScenario0": ("Каждый день: She ___ English.", "Every day: She ___ English."),
        "lab.tenseScenario1": ("Смотри! They ___ football now.", "Look! They ___ football now."),
        "lab.tenseOption00": ("studies", "studies"),
        "lab.tenseOption01": ("is studying", "is studying"),
        "lab.tenseOption10": ("play", "play"),
        "lab.tenseOption11": ("are playing", "are playing"),
        "lab.tenseCorrect": ("Верно: форма подходит к значению и времени действия.", "Correct: the form matches the meaning and time of the action."),
        "lab.tenseIncorrect": ("Проверь подсказку: это привычка или действие прямо сейчас?", "Check the clue: is this a habit or an action happening now?"),
        "lab.tenseExplanation.0.correct": ("Every day обозначает регулярную привычку. Поэтому нужен Present Simple: с she глагол study меняется на studies.", "Every day marks a regular habit, so use the present simple. With she, study changes to studies."),
        "lab.tenseExplanation.0.incorrect": ("Every day указывает на привычку, поэтому подходит Present Simple. Is studying описывает действие, которое происходит сейчас.", "Every day signals a habit, so the present simple fits. Is studying describes an action happening now."),
        "lab.tenseExplanation.1.correct": ("Look! и now показывают действие в процессе сейчас. С they используется are + глагол с окончанием -ing: are playing.", "Look! and now show an action in progress. With they, use are + the -ing form: are playing."),
        "lab.tenseExplanation.1.incorrect": ("Look! и now показывают действие, которое происходит сейчас, а не привычку. Для they нужен Present Continuous: are + глагол с -ing.", "Look! and now describe an action happening now, not a habit. With they, use the present continuous: are + the -ing form."),
        "lab.perfectPrompt": ("Результат, процесс или состояние? Выбери форму, которая лучше передаёт нужный акцент.", "Result, activity, or state? Choose the form that best fits the focus."),
        "lab.perfectSituation": ("Ситуация", "Situation"),
        "lab.perfectScenario0": ("Количество", "Quantity"),
        "lab.perfectScenario1": ("Длительность", "Duration"),
        "lab.perfectScenario2": ("Состояние", "State"),
        "lab.perfectSentence0": ("Maya ___ three chapters so far.", "Maya ___ three chapters so far."),
        "lab.perfectSentence1": ("I ___ for an hour, and I still haven't reached the station.", "I ___ for an hour, and I still haven't reached the station."),
        "lab.perfectSentence2": ("We ___ each other since 2018.", "We ___ each other since 2018."),
        "lab.perfectOption00": ("has been reading", "has been reading"), "lab.perfectOption01": ("has read", "has read"),
        "lab.perfectOption10": ("have waited", "have waited"), "lab.perfectOption11": ("have been waiting", "have been waiting"),
        "lab.perfectOption20": ("have known", "have known"), "lab.perfectOption21": ("have been knowing", "have been knowing"),
        "lab.perfectFeedback00": ("Подумай о словах three chapters: они называют количество результата.", "Look at three chapters: it gives a count of the result."),
        "lab.perfectFeedback01": ("Верно: Present Perfect Simple подчёркивает уже прочитанные главы и их количество.", "Correct: the present perfect simple highlights the chapters read and their number."),
        "lab.perfectFeedback10": ("Simple тоже может говорить о длительности, но здесь мы хотим сильнее выделить продолжающееся ожидание.", "The simple form can also describe duration, but here we want to emphasise the continuing wait."),
