        "lab.input.valueError": ("ValueError: это не целое число; проверь текст и попробуй снова.", "ValueError: this is not a whole number; check the text and try again."),
        "lab.input.rangeLimit": ("Число вне диапазона симулятора. Настоящие целые числа Python могут быть больше.", "This number is outside the simulator's range. Real Python integers can be larger."),
        "lab.input.simulatorLimit": ("Учебная симуляция принимает обычные цифры ASCII, знак и пробелы. Она не исполняет введённый код и не моделирует весь синтаксис int() в Python.", "This learning simulator accepts ordinary ASCII digits, a sign, and surrounding whitespace. It does not execute entered code or model all of Python int() syntax."),
        "lab.rationalHint": ("Меняй x и сравнивай исходную дробь с сокращённой формулой. Следи за значением, запрещённым исходным знаменателем.", "Change x and compare the original fraction with its reduced form. Watch for the input excluded by the original denominator."),
        "lab.rationalFormula": ("Функция f от x равна x в квадрате минус девять, делённое на x минус три.", "The function f of x is x squared minus nine divided by x minus three."),
        "lab.rationalInput": ("Значение x от минус пяти до пяти с шагом четверть", "Value of x from minus five to five in quarter-unit steps"),
        "lab.rationalSelectedInput": ("x = %@", "x = %@"),
        "lab.rationalOriginal": ("Исходная дробь", "Original fraction"),
        "lab.rationalReduced": ("После сокращения: x + 3", "After reducing: x + 3"),
        "lab.rationalUndefined": ("не определена", "undefined"),
        "lab.rationalExcluded": ("x = 3 исключено: исходный знаменатель равен нулю. Упрощённое значение не отменяет это ограничение.", "x = 3 is excluded: the original denominator is zero. The reduced value does not remove that restriction."),
        "lab.rationalDefined": ("При этом x исходная дробь и x + 3 совпадают. Проверь, почему общий множитель можно сокращать.", "At this x, the original fraction and x + 3 agree. Check why the common factor can be cancelled."),
        "lab.routineHint": ("Выбери устойчивое английское выражение, которое подходит к ситуации. Запоминай фразу целиком вместе с глаголом.", "Choose the common English phrase that fits each situation. Remember the whole phrase with its verb."),
        "lab.routineProgress": ("Ситуация %d из %d", "Situation %d of %d"),
        "lab.routinePrompt1": ("Перед занятием я ___ дома.", "Before class, I ___ at home."),
        "lab.routinePrompt2": ("Каждый будний день в семь я ___, а потом одеваюсь.", "At seven each weekday, I ___ and then get dressed."),
        "lab.routinePrompt3": ("Перед выходом в школу я ___.", "Before leaving for school, I ___."),
        "lab.routinePrompt4": ("В полдень мы вместе ___.", "At midday, we ___ together."),
        "lab.routinePrompt5": ("Около десяти вечера я ___.", "At about ten in the evening, I ___."),
        "lab.routineWakeUp": ("wake up", "wake up"),
        "lab.routineGetDressed": ("get dressed", "get dressed"),
        "lab.routineHaveBreakfast": ("have breakfast", "have breakfast"),
        "lab.routineHaveLunch": ("have lunch", "have lunch"),
        "lab.routineHaveDinner": ("have dinner", "have dinner"),
        "lab.routineGoToBed": ("go to bed", "go to bed"),
        "lab.routineCheck": ("Проверить", "Check answer"),
        "lab.routineNext": ("Дальше", "Next"),
        "lab.routineFinish": ("Завершить", "Finish"),
        "lab.routineCorrect": ("Верно. Запомни сочетание целиком.", "Correct. Remember the whole collocation."),
        "lab.routineIncorrect": ("Пока мимо. Подумай о времени и ситуации в предложении.", "Not quite. Think about the time and situation in the sentence."),
        "lab.routineExplanation1": ("Перед занятием дома естественно сказать have breakfast — «позавтракать».", "Before class at home, have breakfast is the natural collocation."),
        "lab.routineExplanation2": ("Сначала человек просыпается — wake up, а потом одевается.", "A person wakes up first, then gets dressed."),
        "lab.routineExplanation3": ("Перед выходом нужно одеться: get dressed.", "Before leaving, you get dressed."),
        "lab.routineExplanation4": ("Полуденная еда — это обед: have lunch.", "The midday meal is lunch: have lunch."),
        "lab.routineExplanation5": ("Около десяти вечера обычно ложатся спать: go to bed.", "At about ten in the evening, people usually go to bed."),
        "lab.routineComplete": ("Все пять ситуаций разобраны. Попробуй составить фразу о своём обычном дне.", "You have worked through all five situations. Now describe one part of your own day."),
        "lab.routineRestart": ("Начать заново", "Start again"),
        "lab.readingHint": ("Сначала поймай общий смысл, затем найди подтверждение в тексте. Незнакомое слово проверяй по контексту.", "Get the gist first, then find evidence in the text. Use context to check an unfamiliar word."),
        "lab.readingProgress": ("Шаг %d из %d", "Step %d of %d"),
        "lab.readingQuestion0": ("Читаешь короткое объявление впервые. Какая цель первого прохода?", "You are reading a short notice for the first time. What is the goal of the first pass?"),
        "lab.readingQuestion1": ("В объявлении сказано, что клуб встречается онлайн во вторник в 4 p.m. Как быстро подтвердить время встречи?", "The notice says the club meets online on Tuesday at 4 p.m. How can you quickly verify the meeting time?"),
        "lab.readingQuestion2": ("В предложении `Students can book the small room` незнакомое слово `book`. Как понять его значение здесь?", "In `Students can book the small room`, the word `book` is unfamiliar. How can you infer its meaning here?"),
        "lab.readingOption0": ("Перевести каждое слово до конца", "Translate every word before continuing"),
        "lab.readingOption1": ("Понять, о чём объявление в целом", "Work out what the notice is mainly about"),
        "lab.readingOption2": ("Сразу запомнить все новые слова", "Memorise every new word immediately"),
        "lab.readingOption3": ("Найти в тексте слова о времени и встрече", "Scan for words about the time and meeting"),
        "lab.readingOption4": ("Искать только название комнаты", "Look only for the room name"),
        "lab.readingOption5": ("Остановиться и перевести всё объявление", "Stop and translate the whole notice"),
        "lab.readingOption6": ("Проверить соседние слова и роль слова в предложении", "Check the nearby words and the word's role in the sentence"),
        "lab.readingOption7": ("Всегда считать, что оно означает книгу", "Always assume it means a book to read"),
        "lab.readingOption8": ("Угадать, не читая соседние слова", "Guess without reading the surrounding words"),
        "lab.readingCheck": ("Проверить", "Check answer"),
        "lab.readingNext": ("Дальше", "Next"),
        "lab.readingFinish": ("Завершить", "Finish"),
        "lab.readingTryAgain": ("Пока нет. Выбери стратегию, которая отвечает именно на поставленный вопрос.", "Not quite. Choose the strategy that answers the question being asked."),
        "lab.readingFeedback0": ("Верно. Первый проход нужен, чтобы получить общий смысл, а не идеальный перевод.", "Correct. The first pass is for the gist, not a perfect translation."),
        "lab.readingFeedback1": ("Верно. Просканируй текст в поиске слов о встрече и времени; затем сверь найденную строку.", "Correct. Scan for words about the meeting and time, then check the sentence you found."),
        "lab.readingFeedback2": ("Верно. Сочетание с комнатой и роль глагола подсказывают значение «забронировать».", "Correct. The room context and the verb's role suggest the meaning “reserve”."),
        "lab.readingComplete": ("Все три шага пройдены. Теперь перескажи объявление одной фразой и укажи, какая строка подтверждает деталь.", "All three steps are complete. Summarise the notice in one sentence and point to the line that supports a detail."),
        "lab.readingRestart": ("Начать заново", "Start again"),
        "lab.stressHint": ("Сначала пойми роль слова в предложении, затем выбери ударный слог. Заглавные буквы показывают ударение; правило для двухсложных пар — подсказка, а не универсальный закон. Сверь звучание с аудио в официальном словаре.", "Use the sentence to identify the word's role, then choose its stressed syllable. Capitals mark stress. The two-syllable pattern is a useful tendency, not a universal rule; check the sound in an official dictionary."),
        "lab.stressListen": ("Слушать пример", "Listen to example"),
        "lab.stressStopAudio": ("Остановить", "Stop"),
        "lab.stressBritishVoice": ("Британский", "British"),
        "lab.stressAmericanVoice": ("Американский", "American"),
        "lab.stressSyntheticAudioNote": ("Синтезированная озвучка macOS; сравни её с оригинальной записью UK/US в словаре.", "Synthetic macOS speech; compare it with the original UK/US dictionary recording."),
        "lab.stressVoiceUnavailable": ("В macOS не найден английский голос UK или US. Добавь английский голос в системных настройках озвучивания.", "No UK or US English voice was found in macOS. Add an English voice in Spoken Content settings."),
        "lab.stressProgress": ("Пример %d из %d", "Example %d of %d"),
        "lab.stressQuestion0": ("Школа прислала подарок: “I received a present from the school.” Где ударение в существительном present?", "The school sent a gift: “I received a present from the school.” Which syllable is stressed in the noun present?"),
        "lab.stressQuestion1": ("Завтра она представит результаты: “She will present the results tomorrow.” Где ударение в глаголе present?", "Tomorrow she will introduce the results: “She will present the results tomorrow.” Which syllable is stressed in the verb present?"),
        "lab.stressQuestion2": ("Запись сохранилась: “The record is stored locally.” Где ударение в существительном record?", "The file was saved: “The record is stored locally.” Which syllable is stressed in the noun record?"),
        "lab.stressQuestion3": ("Сохрани результат: “Please record the result.” Где ударение в глаголе record?", "Save the result: “Please record the result.” Which syllable is stressed in the verb record?"),
        "lab.stressOption.present.0": ("PRE-sent — ударение на первом слоге", "PRE-sent — stress on the first syllable"),
        "lab.stressOption.present.1": ("pre-SENT — ударение на втором слоге", "pre-SENT — stress on the second syllable"),
        "lab.stressOption.record.0": ("RE-cord — ударение на первом слоге", "RE-cord — stress on the first syllable"),
        "lab.stressOption.record.1": ("re-CORD — ударение на втором слоге", "re-CORD — stress on the second syllable"),
        "lab.stressTryAgain": ("Не совпало. Проверь, существительное это или глагол в данном контексте, и послушай оба варианта в словаре.", "Not quite. Check whether the word is a noun or a verb in this context, then listen to both forms in a dictionary."),
        "lab.stressFeedback0": ("Верно: present как существительное обычно имеет ударение на первом слоге. Открой Cambridge Dictionary и сравни звук с глагольной формой.", "Correct: the noun present normally has first-syllable stress. Open Cambridge Dictionary and compare it with the verb."),
        "lab.stressFeedback1": ("Верно: в глаголе present ударение обычно переходит на второй слог. Сравни обе формы в Cambridge Dictionary.", "Correct: the verb present normally has second-syllable stress. Compare both forms in Cambridge Dictionary."),
        "lab.stressFeedback2": ("Верно: существительное record обычно ударяется на первом слоге. Проверь британское и американское аудио в Cambridge Dictionary.", "Correct: the noun record normally has first-syllable stress. Check the UK and US audio in Cambridge Dictionary."),
        "lab.stressFeedback3": ("Верно: глагол record обычно ударяется на втором слоге. Форма глагола может отличаться между акцентами, поэтому слушай нужный вариант.", "Correct: the verb record normally has second-syllable stress. Its vowel quality can vary by accent, so listen to the variety you are learning."),
        "lab.stressCheck": ("Проверить", "Check answer"),
        "lab.stressNext": ("Дальше", "Next"),
        "lab.stressFinish": ("Завершить", "Finish"),
        "lab.stressComplete": ("Все четыре примера пройдены. Теперь произнеси каждую пару и объясни, как контекст помогает распознать ударение.", "All four examples are complete. Now say each pair and explain how context helps you identify the stress."),
        "lab.stressRestart": ("Начать заново", "Start again"),
        "lab.beHint": ("Сначала найди, кто выполняет роль подлежащего, затем выбери местоимение и форму be. Ошибка покажет подсказку; правильный ответ — разбор.", "First identify the subject, then choose a pronoun and a form of be. An incorrect answer reveals a hint; a correct answer reveals the explanation."),
        "lab.beProgress": ("Ситуация %d из %d", "Question %d of %d"),
        "lab.beTryAgain": ("Пока нет. Используй подсказку и попробуй другой вариант.", "Not quite. Use the hint and try another option."),
        "lab.beCheck": ("Проверить", "Check"),
        "lab.beNext": ("Дальше", "Next"),
        "lab.beFinish": ("Завершить", "Finish"),
        "lab.beComplete": ("Все семь ситуаций пройдены. Теперь представь себя и задай собеседнику вопрос с be.", "All seven situations are complete. Now introduce yourself and ask someone a question with be."),
        "lab.beRestart": ("Начать заново", "Start again"),
        "lab.conditionalHint": ("Определи смысл условия прежде, чем смотреть на форму глагола: общее правило, реальная возможность или воображаемая ситуация.", "Identify the meaning before looking at verb forms: a general rule, a real possibility, or an imagined situation."),
        "lab.conditionalProgress": ("Ситуация %d из %d", "Situation %d of %d"),
        "lab.conditionalScenario0": ("Ты объясняешь научную закономерность: металл расширяется при нагревании. Какой тип подходит?", "You are explaining a general scientific rule: metal expands when heated. Which pattern fits?"),
        "lab.conditionalScenario1": ("На завтра есть реальный план: если не будет дождя, команда проведёт наблюдения на улице. Какой тип подходит?", "There is a real plan for tomorrow: if it does not rain, the team will observe outdoors. Which pattern fits?"),
        "lab.conditionalScenario2": ("Ты фантазируешь: если бы у тебя был телескоп, ты мог бы лучше рассмотреть кольца Сатурна. Какой тип подходит?", "You are imagining: if you had a telescope, you could see Saturn's rings more clearly. Which pattern fits?"),
        "lab.conditionalOption0": ("Zero — общее правило: Present Simple → Present Simple", "Zero — general rule: present simple → present simple"),
        "lab.conditionalOption1": ("First — реальная возможность: Present Simple → will + глагол", "First — real possibility: present simple → will + verb"),
        "lab.conditionalOption2": ("Second — воображаемое условие: Past Simple → would + глагол", "Second — imagined condition: past simple → would + verb"),
        "lab.conditionalCheck": ("Проверить", "Check answer"),
        "lab.conditionalNext": ("Дальше", "Next"),
        "lab.conditionalFinish": ("Завершить", "Finish"),
        "lab.conditionalTryAgain": ("Пока нет. Спроси себя, насколько условие реально для говорящего.", "Not quite. Ask how realistic the condition is for the speaker."),
        "lab.conditionalFeedback0": ("Верно: это повторяемая общая закономерность. В обеих частях используется Present Simple.", "Correct: this is a general, repeatable rule. Both clauses use the present simple."),
        "lab.conditionalFeedback1": ("Верно: это реальная возможность в будущем. После if стоит Present Simple, а результат использует will.", "Correct: this is a real future possibility. The if-clause uses the present simple and the result uses will."),
        "lab.conditionalFeedback2": ("Верно: это воображаемое условие. Past Simple показывает дистанцию от реальности, а не обязательно прошлое время.", "Correct: this is an imagined condition. The past form signals distance from reality, not necessarily past time."),
        "lab.conditionalComplete": ("Все три смысла разобраны. Теперь составь собственные примеры для общего правила, плана и гипотезы.", "You have worked through all three meanings. Now make your own examples for a rule, a plan, and a hypothesis."),
        "lab.conditionalRestart": ("Начать заново", "Start again"),
        "lab.reportedHint": ("Определи, что пересказываешь: утверждение, специальный вопрос, вопрос «да/нет» или просьбу. Затем проверь порядок слов и точку отсчёта для времени и слов вроде today.", "Identify what you are reporting: a statement, wh-question, yes/no question, or request. Then check word order and the time reference for tense and words such as today."),
        "lab.reportedProgress": ("Ситуация %d из %d", "Situation %d of %d"),
        "lab.reportedQuestion0": ("В понедельник Лили сказала: “I am working from home today.” Ты пересказываешь это во вторник, после понедельника. Выбери подходящий вариант.", "On Monday, Lily said: “I am working from home today.” You report this on Tuesday, after Monday. Choose the suitable version."),
        "lab.reportedQuestion1": ("Мира задала этот вопрос в понедельник: “Where does the lab keep the samples?” Как пересказать его во вторник по распространённой модели сдвига времени и с правильным порядком слов?", "Mira asked this on Monday: “Where does the lab keep the samples?” How can you report it on Tuesday using the common backshift pattern and correct word order?"),
        "lab.reportedQuestion2": ("Сэм спросил: “Are you available for the review?” Выбери правильный косвенный вопрос с ответом «да/нет».", "Sam asked: “Are you available for the review?” Choose the correct reported yes/no question."),
        "lab.reportedQuestion3": ("Преподаватель вежливо попросил: “Could you send me the notes after class?” Какой вариант сохраняет просьбу?", "The tutor made a polite request: “Could you send me the notes after class?” Which version keeps it as a request?"),
        "lab.reportedOption0.0": ("Lily сказала, что работает из дома сегодня. (Lily said she is working from home today.)", "Lily said she is working from home today."),
        "lab.reportedOption0.1": ("Lily сказала, что работает из дома в тот день. (Lily said she was working from home that day.)", "Lily said she was working from home that day."),
        "lab.reportedOption0.2": ("Lily сообщила, что она работает из дома в тот день. (Lily told that she was working from home that day.)", "Lily told that she was working from home that day."),
        "lab.reportedOption1.0": ("Mira спросила, где лаборатория хранит образцы. (Mira asked where the lab kept the samples.)", "Mira asked where the lab kept the samples."),
        "lab.reportedOption1.1": ("Mira спросила, где лаборатория хранила образцы? (Mira asked where did the lab keep the samples.)", "Mira asked where did the lab keep the samples."),
        "lab.reportedOption1.2": ("Mira спросила, хранит ли лаборатория образцы. (Mira asked if the lab kept the samples.)", "Mira asked if the lab kept the samples."),
        "lab.reportedOption2.0": ("Sam спросил, была ли я доступна для разбора? (Sam asked whether was I available for the review.)", "Sam asked whether was I available for the review."),
        "lab.reportedOption2.1": ("Sam спросил, где я была доступна для разбора. (Sam asked where I was available for the review.)", "Sam asked where I was available for the review."),
        "lab.reportedOption2.2": ("Sam спросил, доступна ли я для разбора. (Sam asked whether I was available for the review.)", "Sam asked whether I was available for the review."),
        "lab.reportedOption3.0": ("Преподаватель спросил, могла ли я отправила конспект. (The tutor asked me if I could sent the notes after class.)", "The tutor asked me if I could sent the notes after class."),
        "lab.reportedOption3.1": ("Преподаватель попросил меня отправить конспект после занятия. (The tutor asked me to send the notes after class.)", "The tutor asked me to send the notes after class."),
        "lab.reportedOption3.2": ("Преподаватель сказал меня отправить конспект. (The tutor said me to send the notes after class.)", "The tutor said me to send the notes after class."),
        "lab.reportedCheck": ("Проверить", "Check answer"),
        "lab.reportedCheckAgain": ("Проверить ещё раз", "Check again"),
        "lab.reportedNext": ("Дальше", "Next"),
        "lab.reportedFinish": ("Завершить", "Finish"),
        "lab.reportedTryAgain": ("Пока нет. Посмотри на подсказку и попробуй ещё раз.", "Not quite. Check the cue and try again."),
        "lab.reportedWrong0.0": ("В этой задаче пересказ идёт на следующий день и проверяет распространённый backshift: используй was working и замени today из исходной реплики на that day. Настоящее время возможно в других контекстах, если факт всё ещё актуален.", "This exercise reports the statement the next day and practises the common backshift pattern: use was working and change today in the original statement to that day. Present tense can remain in other contexts when the fact is still current."),
        "lab.reportedWrong0.2": ("После tell укажи, кому сообщили: told me. Если адресат не назван, используй said that…", "After tell, name the listener: told me. If you do not name the listener, use said that…"),
        "lab.reportedWrong1.1": ("В косвенном вопросе не сохраняй обратный порядок прямого вопроса. Убери did и поставь подлежащее перед глаголом: where the lab kept…", "Do not keep direct-question inversion in an indirect question. Drop did and put the subject before the verb: where the lab kept…"),
        "lab.reportedWrong1.2": ("Исходный вопрос начинается с where, значит он спрашивает о месте, а не предполагает ответ «да/нет». Сохрани where: where the lab kept…", "The original question begins with where, so it asks about a place rather than a yes/no answer. Keep where: where the lab kept…"),
        "lab.reportedWrong2.0": ("В придаточной части после whether используй порядок утверждения: whether I was, а не whether was I.", "Use statement word order after whether: whether I was, not whether was I."),
        "lab.reportedWrong2.1": ("Where спрашивает о месте, но исходный вопрос проверяет, доступна ли я: это вопрос «да/нет». Используй if или whether.", "Where asks about a place, but the original asks whether I am available: it is a yes/no question. Use if or whether."),
        "lab.reportedWrong3.0": ("После could нужен начальный глагол send, не sent. Но здесь важно передать просьбу, а не вопрос «можешь ли»: используй ask + человек + to + глагол.", "Use the base verb send after could, not sent. But this task reports a request, not a yes/no question: use ask + person + to + verb."),
        "lab.reportedWrong3.2": ("Для просьбы используй ask + человек + to + глагол: asked me to send. Say не ставится прямо перед местоимением адресата в такой конструкции.", "For a request, use ask + person + to + verb: asked me to send. Say does not take the listener pronoun directly in this construction."),
        "lab.reportedFeedback0": ("Верно. am working сдвигается к was working, потому что пересказ ведётся после said. В понедельник today становится that day во вторничном пересказе.", "Correct. am working backshifts to was working after said. In a Tuesday report, Monday’s today becomes that day."),
        "lab.reportedFeedback1": ("Верно. Здесь выбрана распространённая форма с backshift: в косвенном вопросе сохраняется where, используется порядок утверждения, а does исчезает и основной глагол получает форму kept.", "Correct. This is the common backshifted form: keep where, use statement order, drop does, and backshift the main verb to kept."),
        "lab.reportedFeedback2": ("Верно. Вопрос «да/нет» вводится через if или whether; внутри используется порядок утверждения: I was, а не was I.", "Correct. A yes/no question uses if or whether; inside the clause, use statement order: I was, not was I."),
        "lab.reportedFeedback3": ("Верно. Распространённая модель просьбы — ask + человек + to + глагол: asked me to send. Если называешь адресата после say, используй конструкцию say something to somebody, а не say somebody.", "Correct. A common request pattern is ask + person + to + verb: asked me to send. When naming the listener after say, use say something to somebody, not say somebody."),
        "lab.reportedComplete": ("Все четыре формы проверены. Теперь перескажи собственный пример и объясни, какие слова изменились из-за контекста.", "All four forms are practised. Now report your own example and explain which words changed because of context."),
        "lab.reportedRestart": ("Начать заново", "Start again"),
        "lab.animalGroupHint": ("Сравни строение и питание. Один общий признак ещё не доказывает, к какой группе относится организм.", "Compare structure and nutrition. One shared feature alone does not prove an organism's group."),
        "lab.animalGroupProgress": ("Пример %d из %d", "Example %d of %d"),
        "lab.animalGroupQ1": ("Какой пример показывает, что взрослое животное может быть неподвижным?", "Which example shows that an adult animal can be sessile?"),
        "lab.animalGroupQ1A": ("Губка, прикреплённая к поверхности", "A sponge attached to a surface"),
        "lab.animalGroupQ1B": ("Подсолнечник, поворачивающийся к свету", "A sunflower turning toward light"),
        "lab.animalGroupQ1C": ("Бактерия, движущаяся жгутиком", "A bacterium moving with a flagellum"),
        "lab.animalGroupQ2": ("Что лучше описывает дрожжи?", "Which description best fits yeast?"),
        "lab.animalGroupQ2A": ("Одноклеточное животное, потому что это эукариот", "A unicellular animal because it is a eukaryote"),
        "lab.animalGroupQ2B": ("Одноклеточный гриб", "A unicellular fungus"),
        "lab.animalGroupQ2C": ("Бактерия с клеточным ядром", "A bacterium with a cell nucleus"),
        "lab.animalGroupQ3": ("Какой вывод надёжнее всего отличает бактерию от животного?", "Which conclusion most reliably distinguishes a bacterium from an animal?"),
        "lab.animalGroupQ3A": ("Она движется, значит это животное", "It moves, so it is an animal"),
        "lab.animalGroupQ3B": ("Она живёт в воде, значит это животное", "It lives in water, so it is an animal"),
        "lab.animalGroupQ3C": ("У неё нет клеточного ядра; животные — эукариоты", "It lacks a cell nucleus; animals are eukaryotes"),
        "lab.animalGroupQ4": ("Почему нельзя считать любой многоклеточный эукариот животным?", "Why can’t every multicellular eukaryote be called an animal?"),
        "lab.animalGroupQ4A": ("Потому что многоклеточные эукариоты всегда неподвижны", "Because multicellular eukaryotes are always sessile"),
        "lab.animalGroupQ4B": ("Растения тоже многоклеточные эукариоты", "Plants are also multicellular eukaryotes"),
        "lab.animalGroupQ4C": ("Потому что у животных нет клеток", "Because animals have no cells"),
