        "lab.algorithmEligibilityInvalid": ("возраст вне контракта — вход нужно отклонить", "age is outside the contract and must be rejected"),
        "lab.algorithmEligibilityIncorrect": ("Сверь возраст с допустимым диапазоном и ближайшими значениями порога 65 лет.", "Check the valid age range and the values immediately around the 65-year threshold."),
        "lab.algorithmEligibilityTypicalBelowExplanation": ("Возраст 40 находится внутри допустимого диапазона и далеко от порога; скидка не положена.", "Age 40 is valid and far from the threshold; the discount does not apply."),
        "lab.algorithmEligibilityBelowExplanation": ("64 — допустимое значение непосредственно ниже порога 65; скидка ещё не положена.", "64 is a valid value immediately below the threshold of 65; the discount does not apply yet."),
        "lab.algorithmEligibilityAtExplanation": ("65 проверяет сам порог. При правиле age ≥ 65 скидка уже положена.", "65 checks the threshold itself. Under age ≥ 65, the discount applies."),
        "lab.algorithmEligibilityTypicalAboveExplanation": ("66 — допустимое значение сразу выше порога; скидка положена.", "66 is a valid value just above the threshold; the discount applies."),
        "lab.algorithmEligibilityInvalidBelowExplanation": ("−1 меньше нижней границы 0 и должен быть отклонён до проверки скидки.", "−1 is below the lower bound of 0 and must be rejected before checking the discount."),
        "lab.algorithmEligibilityInvalidAboveExplanation": ("121 больше верхней границы 120 и должен быть отклонён до проверки скидки.", "121 is above the upper bound of 120 and must be rejected before checking the discount."),
        "lab.algorithmInitializeHotDayCount": ("Установить счётчик жарких дней в 0", "Set the hot-day counter to 0"),
