        "lab.git.title": ("Git: ветка, коммит и командная проверка", "Git: branch, commit, and team review"),
        "lab.git.hint": ("Проведи изменение от рабочей папки до отдельной ветки и проверки командой. Выбирай только то, что должно попасть в историю.", "Move a change from the working tree to an isolated branch and team review. Choose only what belongs in history."),
        "lab.git.files": ("Сценарий: изменены lesson.py и тест; debug.log не отслеживается. После локального коммита начинаем отдельную задачу в feature-ветке.", "Scenario: lesson.py and its test changed; debug.log is untracked. After the local commit, start a separate task on a feature branch."),
        "lab.git.progress": ("Шаг %d из %d", "Step %d of %d"),
        "lab.git.snapshotLabel": ("Вывод git status", "git status output"),
        "lab.git.snapshot.unstaged": (" M lesson.py\n M tests/test_lesson.py\n?? debug.log", " M lesson.py\n M tests/test_lesson.py\n?? debug.log"),
        "lab.git.snapshot.staged": ("M  lesson.py\nM  tests/test_lesson.py\n?? debug.log", "M  lesson.py\nM  tests/test_lesson.py\n?? debug.log"),
        "lab.git.snapshot.committed": ("?? debug.log", "?? debug.log"),
        "lab.git.snapshot.featureBranch": ("## feature/add-lesson-check\n M lesson.py\n M tests/test_lesson.py\n?? debug.log", "## feature/add-lesson-check\n M lesson.py\n M tests/test_lesson.py\n?? debug.log"),
        "lab.git.snapshot.featureStaged": ("## feature/add-lesson-check\nM  lesson.py\nM  tests/test_lesson.py\n?? debug.log", "## feature/add-lesson-check\nM  lesson.py\nM  tests/test_lesson.py\n?? debug.log"),
        "lab.git.snapshot.featureCommitted": ("## feature/add-lesson-check\n?? debug.log", "## feature/add-lesson-check\n?? debug.log"),
        "lab.git.snapshot.featurePublished": ("## feature/add-lesson-check...origin/feature/add-lesson-check\n?? debug.log", "## feature/add-lesson-check...origin/feature/add-lesson-check\n?? debug.log"),
        "lab.git.snapshot.pullRequest": ("Ветка опубликована; pull request ждёт CI и проверки коллег.", "Branch published; the pull request is awaiting CI and teammate review."),
        "lab.git.snapshotInfo.unstaged": ("Файлы изменены, но пока не добавлены в коммит. Сначала изучи статус и diff.", "Files have changed but are not staged for a commit. Inspect status and the diff first."),
        "lab.git.snapshotInfo.staged": ("Файлы урока и теста подготовлены к коммиту; посторонний debug.log всё ещё отдельно.", "The lesson and test files are staged; the unrelated debug.log remains separate."),
        "lab.git.snapshotInfo.committed": ("Изменения сохранены в локальной истории. debug.log остался неотслеживаемым.", "The changes are saved in local history. debug.log remains untracked."),
        "lab.git.snapshotInfo.featureBranch": ("Новая работа изолирована в feature-ветке. Основная ветка остаётся на прежнем коммите; debug.log не добавлен.", "The new work is isolated on a feature branch. The base branch stays at its earlier commit; debug.log is not staged."),
        "lab.git.snapshotInfo.featureStaged": ("В staging попали только урок и тест; проверь этот снимок перед коммитом.", "Only the lesson and test are staged; review this snapshot before committing."),
        "lab.git.snapshotInfo.featureCommitted": ("Коммит находится в feature-ветке и пока только в локальной истории.", "The commit is on the feature branch and only in local history so far."),
        "lab.git.snapshotInfo.featurePublished": ("Upstream настроен на origin/feature/add-lesson-check; изменения опубликованы отдельно от основной ветки.", "Upstream tracks origin/feature/add-lesson-check; the change is published separately from the base branch."),
        "lab.git.snapshotInfo.pullRequest": ("Pull request предлагает изменение для проверки. Выполни CI, изучи diff и учти правила репозитория перед слиянием.", "The pull request proposes a change for review. Run CI, inspect the diff, and follow repository rules before merging."),
        "lab.git.prompt.status": ("Перед изменениями посмотри, какие файлы изменены и какие не отслеживаются.", "Before acting, inspect which files changed and which are untracked."),
        "lab.git.prompt.diff": ("Проверь содержимое уже отслеживаемых изменений перед staging.", "Review the tracked file changes before staging them."),
        "lab.git.prompt.add": ("Добавь в staging только файлы урока и теста; не захватывай debug.log.", "Stage only the lesson and test files; leave debug.log out."),
        "lab.git.prompt.diffCached": ("Перед коммитом проверь точный снимок, который попадёт в историю.", "Before committing, inspect the exact snapshot that will enter history."),
        "lab.git.prompt.commit": ("Запиши подготовленный снимок локальным коммитом с понятным сообщением.", "Record the staged snapshot in a local commit with a clear message."),
        "lab.git.prompt.verify": ("Проверь итоговое состояние и убедись, что debug.log не попал в коммит.", "Check the final state and confirm that debug.log was not committed."),
        "lab.git.prompt.createBranch": ("Локальное изменение завершено. Начни новую задачу отдельно, чтобы не работать прямо в основной ветке.", "The local change is complete. Start the next task separately instead of working directly on the base branch."),
        "lab.git.prompt.stageBranchFiles": ("В новой ветке изменены lesson.py и тест. Подготовь их, оставив debug.log вне снимка.", "In the new branch, lesson.py and its test changed. Stage them while keeping debug.log out of the snapshot."),
        "lab.git.prompt.reviewBranchSnapshot": ("Перед коммитом проверь точное содержимое staging для новой ветки.", "Before committing, inspect the exact staged snapshot for the new branch."),
        "lab.git.prompt.commitBranch": ("Сохрани проверенные изменения отдельным коммитом feature-ветки.", "Record the reviewed changes in a separate feature-branch commit."),
        "lab.git.prompt.publishBranch": ("Опубликуй feature-ветку и свяжи её с upstream, не отправляя основную ветку.", "Publish the feature branch and set its upstream without pushing the base branch."),
        "lab.git.prompt.openPullRequest": ("Ветка отправлена. Как передать изменение команде на проверку и интеграцию?", "The branch is pushed. How should you hand the change to the team for review and integration?"),
        "lab.git.command.status": ("git status", "git status"),
        "lab.git.command.diff": ("git diff", "git diff"),
        "lab.git.command.diffCached": ("git diff --cached", "git diff --cached"),
        "lab.git.command.addNamed": ("git add lesson.py tests/test_lesson.py", "git add lesson.py tests/test_lesson.py"),
        "lab.git.command.addAll": ("git add .", "git add ."),
        "lab.git.command.commit": ("git commit -m \"Improve lesson input checks\"", "git commit -m \"Improve lesson input checks\""),
        "lab.git.command.push": ("git push", "git push"),
        "lab.git.command.switchCreate": ("git switch -c feature/add-lesson-check", "git switch -c feature/add-lesson-check"),
        "lab.git.command.switchMain": ("git switch main", "git switch main"),
        "lab.git.command.switchForceCreate": ("git switch -C feature/add-lesson-check", "git switch -C feature/add-lesson-check"),
        "lab.git.command.addLog": ("git add debug.log", "git add debug.log"),
        "lab.git.command.commitFeature": ("git commit -m \"Add lesson check\"", "git commit -m \"Add lesson check\""),
        "lab.git.command.pushUpstream": ("git push -u origin feature/add-lesson-check", "git push -u origin feature/add-lesson-check"),
        "lab.git.command.pushMain": ("git push origin main", "git push origin main"),
        "lab.git.command.forcePush": ("git push --force origin feature/add-lesson-check", "git push --force origin feature/add-lesson-check"),
        "lab.git.command.mergeMain": ("git merge feature/add-lesson-check", "git merge feature/add-lesson-check"),
        "lab.git.action.openPullRequest": ("Открой pull request в GitHub, приложи описание, проверь CI и попроси ревью.", "Open a GitHub pull request, describe the change, check CI, and request review."),
        "lab.git.explanation.status": ("git status показывает изменённые и неотслеживаемые файлы до подготовки коммита.", "git status shows modified and untracked files before you prepare a commit."),
        "lab.git.explanation.diff": ("git diff помогает проверить изменения в отслеживаемых файлах до staging.", "git diff reviews changes in tracked files before staging."),
        "lab.git.explanation.add": ("Явно названные пути добавляют в снимок только нужные файлы. git add . заодно захватил бы debug.log.", "Named paths stage only the intended files. git add . would also capture debug.log."),
        "lab.git.explanation.diffCached": ("git diff --cached показывает именно подготовленные изменения, которые войдут в следующий коммит.", "git diff --cached shows the staged changes that will enter the next commit."),
        "lab.git.explanation.commit": ("git commit записывает staging-снимок в локальную историю; он сам по себе ничего не отправляет.", "git commit records the staged snapshot in local history; it does not send it anywhere by itself."),
        "lab.git.explanation.verify": ("Повторный git status подтверждает итог: файлы урока и теста сохранены, посторонний debug.log не добавлен.", "A final git status confirms the result: lesson and test are recorded, and the unrelated debug.log was not added."),
        "lab.git.explanation.createBranch": ("git switch -c создаёт ветку от текущего коммита и сразу переключает на неё. Вариант -C может сбросить уже существующую ветку; здесь он не нужен.", "git switch -c creates a branch from the current commit and switches to it. -C can reset an existing branch, so it is not appropriate here."),
        "lab.git.explanation.stageBranchFiles": ("Явно укажи файлы урока и теста. git add . или добавление debug.log включило бы посторонний файл.", "Name the lesson and test explicitly. git add . or staging debug.log would include an unrelated file."),
        "lab.git.explanation.reviewBranchSnapshot": ("git diff --cached показывает именно тот снимок, который станет коммитом. git diff показывает unstaged-изменения, а status — состояние файлов.", "git diff --cached shows the exact snapshot that will become the commit. git diff shows unstaged changes, while status reports file states."),
        "lab.git.explanation.commitBranch": ("Коммит записывает подготовленный снимок в историю текущей feature-ветки; основная ветка и удалённый репозиторий не меняются.", "The commit records the staged snapshot on the current feature branch; it does not change the base branch or remote repository."),
        "lab.git.explanation.publishBranch": ("git push -u origin <ветка> публикует именно эту ветку и задаёт upstream для последующих push/pull без аргументов.", "git push -u origin <branch> publishes that branch and sets its upstream for later argument-free push/pull operations."),
        "lab.git.explanation.openPullRequest": ("Pull request предлагает изменения для обсуждения и ревью; он не сливает их сам. Проверь diff и CI, ответь на замечания и сливай по правилам репозитория. git merge в локальной основной ветке обходит этот этап.", "A pull request proposes changes for discussion and review; it does not merge them by itself. Inspect the diff and CI, address feedback, and merge according to repository policy. A local git merge into the base branch bypasses this review step."),
        "lab.git.correct": ("Верно: учебный сценарий сделал один безопасный следующий шаг.", "Correct: the teaching scenario took one safe next step."),
        "lab.git.incorrect": ("Пока нет. Прочитай разбор, затем выбери шаг снова.", "Not yet. Read the explanation, then choose again."),
        "lab.git.check": ("Проверить команду", "Check command"),
        "lab.git.next": ("Следующий шаг", "Next step"),
        "lab.git.restart": ("Начать сценарий заново", "Restart the scenario"),
        "lab.git.complete": ("Изменение опубликовано отдельной веткой и передано команде на ревью; оно ещё не слито.", "The change is published on a separate branch and handed to the team for review; it has not been merged."),
        "lab.git.limit": ("Это безопасная симуляция: приложение не запускает команды Git и не меняет настоящий репозиторий.", "This is a safe simulation: the app does not run Git commands or change a real repository."),
        "lab.fileTrace.hint": ("Разбери, что произойдёт при чтении файла. Выбирай конкретный ожидаемый результат: файл отсутствует, текст нельзя преобразовать в число или сумма успешно вычислена.", "Trace what happens while reading a file. Choose the specific outcome: the file is missing, text cannot be converted to a number, or the sum is computed successfully."),
        "lab.fileTrace.scenario": ("Ситуация", "Situation"),
        "lab.fileTrace.scenario.missing": ("Файл scores.txt отсутствует", "The scores.txt file is missing"),
        "lab.fileTrace.scenario.invalid-number": ("В файле есть строка twelve", "The file contains the line twelve"),
        "lab.fileTrace.scenario.valid-numbers": ("В файле числа 7 и −3", "The file contains 7 and −3"),
        "lab.fileTrace.code": ("Чтение числового файла с обработкой ошибок", "Read a numeric file with error handling"),
        "lab.fileTrace.question": ("Какой результат соответствует этой ситуации?", "Which outcome matches this situation?"),
        "lab.fileTrace.outcome.missing": ("Сработает FileNotFoundError: файл не открылся", "FileNotFoundError: the file could not be opened"),
        "lab.fileTrace.outcome.invalid": ("Сработает ValueError: строка не является числом", "ValueError: the line is not a number"),
        "lab.fileTrace.outcome.success": ("Функция завершится и вернёт сумму 4", "The function completes and returns the sum 4"),
        "lab.fileTrace.correct": ("Верно. Теперь свяжи исходную ситуацию с типом ошибки.", "Correct. Connect the situation to the error type."),
        "lab.fileTrace.incorrect": ("Пока нет. Проверь, на каком именно шаге возникает проблема.", "Not quite. Check which exact step causes the problem."),
        "lab.fileTrace.explanation.missing": ("Открытие завершится ошибкой до чтения строк. FileNotFoundError — частный случай OSError; он перехватывается своим обработчиком.", "Opening fails before any lines are read. FileNotFoundError is a specific OSError and matches its dedicated handler."),
        "lab.fileTrace.explanation.invalid": ("Файл удалось открыть, но int(\"twelve\") не может преобразовать слово в целое число и вызывает ValueError.", "The file opened, but int(\"twelve\") cannot convert a word to an integer and raises ValueError."),
        "lab.fileTrace.explanation.success": ("Обе строки преобразуются: 7 + (−3) = 4. Блок with закрывает файл после чтения.", "Both lines convert successfully: 7 + (−3) = 4. The with block closes the file after reading."),
        "lab.fileTrace.check": ("Проверить ответ", "Check answer"),
