        "lab.sql.title": ("Схема, запрос и индекс", "Schema, query, and index"),
        "lab.sql.hint": ("Собери таблицу с понятными ограничениями, отфильтруй учебные записи и выбери индекс под повторяющийся фильтр.", "Design a table with clear constraints, filter the sample rows, and choose an index for a repeated filter."),
        "lab.sql.sampleTable": ("Учебные строки: тема | минуты", "Sample rows: topic | minutes"),
        "lab.sql.progress": ("Шаг %d из %d", "Step %d of %d"),
        "lab.sql.schema.prompt": ("Нужна таблица с уникальным id, обязательными темой и длительностью, а длительность не может быть отрицательной. Какое определение задаёт все эти правила?", "Create a table with a unique id, required topic and duration, and no negative durations. Which definition enforces all these rules?"),
        "lab.sql.schema.choice.loose": ("Оставить id и длительность без обязательности и ограничений.", "Leave id and duration optional and unconstrained."),
        "lab.sql.schema.choice.guarded": ("Задать первичный ключ, NOT NULL для данных и CHECK для неотрицательной длительности.", "Use a primary key, NOT NULL for required fields, and CHECK for a non-negative duration."),
        "lab.sql.schema.choice.mixedTypes": ("Хранить длительность текстом и не проверять её значение.", "Store duration as text and do not validate its value."),
        "lab.sql.schema.explanation": ("Ограничения документируют инварианты и отклоняют часть недопустимых записей. Эта схема использует синтаксис SQLite; типовая система и нюансы ограничений зависят от СУБД.", "Constraints document invariants and reject some invalid writes. This schema uses SQLite syntax; typing and constraint details vary by database."),
        "lab.sql.schema.code": ("CREATE TABLE study_sessions (\n    id INTEGER PRIMARY KEY,\n    topic TEXT NOT NULL,\n    minutes INTEGER NOT NULL CHECK (minutes >= 0)\n);", "CREATE TABLE study_sessions (\n    id INTEGER PRIMARY KEY,\n    topic TEXT NOT NULL,\n    minutes INTEGER NOT NULL CHECK (minutes >= 0)\n);"),
        "lab.sql.query.prompt": ("Выбери темы занятий длительностью от 30 минут и покажи самую длинную первой.", "Select sessions lasting at least 30 minutes and show the longest first."),
        "lab.sql.query.choice.filteredOrdered": ("Выбрать topic и minutes, применить фильтр minutes >= 30, затем сортировать по убыванию.", "Select topic and minutes, filter minutes >= 30, then sort descending."),
        "lab.sql.query.choice.allRows": ("Выбрать все столбцы и все строки без фильтра.", "Select every column and row without filtering."),
        "lab.sql.query.choice.filteredUnordered": ("Отфильтровать строки, но отсортировать по возрастанию длительности.", "Filter the rows but sort by duration ascending."),
        "lab.sql.query.explanation": ("WHERE оставляет подходящие строки, а ORDER BY minutes DESC ставит большую длительность раньше. Запрос читает данные и не меняет таблицу.", "WHERE keeps matching rows, and ORDER BY minutes DESC puts longer durations first. The query reads data without changing the table."),
        "lab.sql.query.code": ("SELECT topic, minutes\nFROM study_sessions\nWHERE minutes >= 30\nORDER BY minutes DESC;", "SELECT topic, minutes\nFROM study_sessions\nWHERE minutes >= 30\nORDER BY minutes DESC;"),
        "lab.sql.index.prompt": ("Запрос часто фильтрует большую таблицу по minutes. Какой индекс подходит этому условию?", "The query often filters a large table by minutes. Which index matches that condition?"),
        "lab.sql.index.choice.topic": ("Создать индекс только по topic.", "Create an index on topic only."),
        "lab.sql.index.choice.everything": ("Индексировать каждый столбец без измерений.", "Index every column without measuring."),
        "lab.sql.index.choice.minutes": ("Создать индекс по minutes и проверить выбранный план запроса.", "Create an index on minutes and inspect the chosen query plan."),
        "lab.sql.index.explanation": ("Индекс по minutes может помочь подходящему фильтру, но планировщик сам решает, использовать ли его. Результат запроса не меняется; индекс занимает место и требует обновления при записи.", "An index on minutes may help a matching filter, but the planner decides whether to use it. Query results stay the same; the index takes space and must be maintained on writes."),
        "lab.sql.index.code": ("CREATE INDEX idx_study_sessions_minutes\nON study_sessions(minutes);", "CREATE INDEX idx_study_sessions_minutes\nON study_sessions(minutes);"),
        "lab.sql.correct": ("Верно", "Correct"),
        "lab.sql.incorrect": ("Проверь требование и попробуй ещё раз", "Check the requirement and try again"),
        "lab.sql.check": ("Проверить", "Check"),
        "lab.sql.next": ("Дальше", "Next"),
        "lab.sql.complete": ("Схема, выборка и индекс разобраны", "Schema, query, and index reviewed"),
        "lab.sql.restart": ("Повторить цикл", "Restart the practice"),
        "lab.sql.limit": ("Это фиксированная учебная модель: она не запускает SQL и не открывает базу. Реальный план SQLite зависит от данных и статистики; индекс сам по себе не гарантирует ускорение.", "This is a fixed teaching model: it runs no SQL and opens no database. A real SQLite plan depends on data and statistics; an index alone does not guarantee a speedup."),
        "lab.transaction.hint": ("Наблюдай разницу между рабочими и сохранёнными балансами. Меняй состояние по одному SQL-шагу; после сбоя сравни эффект COMMIT и ROLLBACK.", "Compare working and saved balances. Advance one SQL step at a time; after a failure, compare COMMIT with ROLLBACK."),
