        "labkit.title.DomainRangeLab": ("Область определения и значения", "Domain and range"),
        "labkit.title.OsmosisLab": ("Осмос: куда пойдёт вода", "Osmosis: which way the water goes"),
        "labkit.title.SymmetryLab": ("Симметрия тела", "Body symmetry"),
